__hydrateVak("havo","wb",{"A":{"sv":[{"v":"Wat lees je af op de y-as bij x = 0 van een grafiek?","o":["de beginwaarde","de richtingscoëfficiënt","het nulpunt","de periode"],"c":0,"d":2,"u":"Bij x = 0 lees je de beginwaarde af.","uo":["Klopt: bij x = 0 lees je de beginwaarde af.","Nee, dat is de helling.","Nee, dat is waar de grafiek de x-as snijdt.","Nee, dat hoort bij periodieke functies."],"uh":"Bij x = 0 op de y-as lees je de beginwaarde af."},{"v":"Hoe herken je een lineair verband in een grafiek?","o":["aan een dalende kromme","aan een rechte lijn met een constante stijging per eenheid","aan een parabool","aan een sinusgolf"],"c":1,"d":2,"u":"Lineair betekent een rechte lijn.","uo":["Nee, dat is geen rechte lijn.","Klopt: lineair betekent een rechte lijn.","Nee, dat is kwadratisch.","Nee, dat is goniometrisch."],"uh":"Lineair verband: een rechte lijn met constante stijging."},{"v":"Wat is substitutie bij het oplossen van een stelsel vergelijkingen?","o":["de grafieken inkleuren","beide vergelijkingen optellen","één variabele uitdrukken in de andere en dat invullen","alles door 2 delen"],"c":2,"d":3,"u":"Je vervangt een variabele door een uitdrukking.","uo":["Nee, dat helpt niet.","Nee, dat is de eliminatiemethode.","Klopt: je vervangt een variabele door een uitdrukking.","Nee, dat lost het stelsel niet op."],"uh":"Substitutie: één variabele uitdrukken en invullen."},{"v":"Bereken de richtingscoëfficiënt van de lijn door (0, 1) en (2, 7).","o":["4","6","2","3"],"c":3,"d":2,"u":"(7 − 1)/(2 − 0) = 3.","uo":["Nee, 6/2 = 3.","Nee, dat is alleen Δy.","Nee, dat is alleen Δx.","Klopt: (7 − 1)/(2 − 0) = 3."],"uh":"Richtingscoëfficiënt: rc = Δy gedeeld door Δx."},{"v":"Ontbind in factoren: x² − 9.","o":["(x − 3)(x + 3)","(x − 3)²","(x + 9)(x − 1)","(x − 9)(x + 1)"],"c":0,"d":2,"u":"Verschil van kwadraten.","uo":["Klopt: verschil van kwadraten.","Nee, dat geeft x² − 6x + 9.","Nee, dat klopt niet.","Nee, dat klopt niet."],"uh":"Verschil van kwadraten: a² − b² = (a − b)(a + b)."},{"v":"Los op: 2x + 6 = 0.","o":["x = 3","x = −3","x = −6","x = 6"],"c":1,"d":1,"u":"2x = −6, dus x = −3.","uo":["Nee, let op het minteken.","Klopt: 2x = −6, dus x = −3.","Nee, je moet nog door 2 delen.","Nee, dat teken en die deling kloppen niet."],"uh":"Haal de losse term over en deel door de factor."},{"v":"Wat is de discriminant D en wat betekent D < 0?","o":["D = 2a; D < 0 betekent één oplossing","D = b + c; D < 0 betekent twee oplossingen","D = b² − 4ac; D < 0 betekent geen reële oplossingen","D bestaat niet"],"c":2,"d":3,"u":"Bij D < 0 zijn er geen reële oplossingen.","uo":["Nee, dat klopt niet.","Nee, de formule klopt niet.","Klopt: bij D < 0 zijn er geen reële oplossingen.","Nee, D bestaat wel."],"uh":"De discriminant D = b² − 4ac telt de reële oplossingen."},{"v":"Herleid: (x − 1)(x + 1).","o":["x² − x − 1","x² + 1","x² − 2x + 1","x² − 1"],"c":3,"d":2,"u":"Verschil van kwadraten, x² − 1.","uo":["Nee, de kruistermen vallen weg.","Nee, het teken klopt niet.","Nee, dat is (x − 1)².","Klopt: verschil van kwadraten, x² − 1."],"uh":"Merkwaardig product: (a − b)(a + b) = a² − b²."},{"v":"Wat betekent exact rekenen?","o":["met breuken en wortels doorrekenen zonder af te ronden","altijd op twee decimalen afronden","de rekenmachine gebruiken","alleen met hele getallen werken"],"c":0,"d":2,"u":"Exact is zonder afronden doorrekenen.","uo":["Klopt: exact is zonder afronden doorrekenen.","Nee, dat is juist afgerond.","Nee, dat geeft vaak een benadering.","Nee, breuken en wortels mogen juist."],"uh":"Exact rekenen: doorrekenen met breuken en wortels."},{"v":"Los op: x² = 16.","o":["x = 4","x = ±4","x = 8","x = ±8"],"c":1,"d":2,"u":"Zowel 4 als −4 in het kwadraat geeft 16.","uo":["Nee, je mist de negatieve oplossing.","Klopt: zowel 4 als −4 in het kwadraat geeft 16.","Nee, 8² = 64.","Nee, √16 = 4."],"uh":"De vergelijking x² = a heeft twee oplossingen: x = ±√a."},{"v":"Wat is de oplossing van een stelsel van twee vergelijkingen?","o":["het snijpunt met de y-as","de som van beide vergelijkingen","de waarden van x en y die aan beide vergelijkingen voldoen","het grootste getal"],"c":2,"d":2,"u":"De oplossing voldoet aan beide.","uo":["Nee, dat is één punt van één lijn.","Nee, dat is een tussenstap, geen oplossing.","Klopt: de oplossing voldoet aan beide.","Nee, dat is geen oplossing."],"uh":"Een stelsel: de x en y die aan beide vergelijkingen voldoen."},{"v":"Wat is de richtingscoëfficiënt van y = 3x − 2?","o":["1","−2","2","3"],"c":3,"d":2,"u":"De rc is de factor voor x, dus 3.","uo":["Nee, dat klopt niet.","Nee, dat is de beginwaarde.","Nee, dat klopt niet.","Klopt: de rc is de factor voor x, dus 3."],"uh":"In y = a·x + b is a de richtingscoëfficiënt."},{"v":"Een rechte lijn met een constante stijging per stap. Welk begrip past hierbij?","o":["Lineair verband","Exact rekenen","Herleiden","Stelsel vergelijkingen"],"c":0,"d":1,"u":"Een rechte lijn met een constante stijging per stap. Dat past bij Lineair verband: rechte lijn.","uo":["Klopt: rechte lijn.","Nee, dat hoort bij Exact rekenen: niet afronden.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven.","Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen."],"uh":"Lineair verband: rechte lijn."},{"v":"Het getal b kwadraat min 4ac dat het aantal oplossingen bepaalt. Om welk begrip gaat het?","o":["Substitutie","Discriminant","Richtingscoëfficiënt","Exact rekenen"],"c":1,"d":1,"u":"Het getal b kwadraat min 4ac dat het aantal oplossingen bepaalt. Dat past bij Discriminant: b² − 4ac.","uo":["Nee, dat hoort bij Substitutie: invullen in de andere vergelijking.","Klopt: b² − 4ac.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Exact rekenen: niet afronden."],"uh":"Discriminant: b² − 4ac."},{"v":"De uitdrukking b kwadraat min 4ac. Welk begrip herken je hier?","o":["Richtingscoëfficiënt","Kwadratische vergelijking","Discriminant","Substitutie"],"c":2,"d":3,"u":"De uitdrukking b kwadraat min 4ac. Dat past bij Discriminant: b² − 4ac.","uo":["Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x².","Klopt: b² − 4ac.","Nee, dat hoort bij Substitutie: invullen in de andere vergelijking."],"uh":"Discriminant: b² − 4ac."},{"v":"Een som als product schrijven. Wat is hier aan de hand?","o":["Kwadratische vergelijking","Stelsel vergelijkingen","Exact rekenen","Ontbinden in factoren"],"c":3,"d":1,"u":"Een som als product schrijven. Dat past bij Ontbinden in factoren: som als product.","uo":["Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x².","Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Nee, dat hoort bij Exact rekenen: niet afronden.","Klopt: som als product."],"uh":"Ontbinden in factoren: som als product."},{"v":"Je schrijft x kwadraat min negen als een product van twee haakjes. Welk begrip past hierbij?","o":["Ontbinden in factoren","Herleiden","Beginwaarde","Richtingscoëfficiënt"],"c":0,"d":3,"u":"Je schrijft x kwadraat min negen als een product van twee haakjes. Dat past bij Ontbinden in factoren: som als product.","uo":["Klopt: som als product.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven.","Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx."],"uh":"Ontbinden in factoren: som als product."},{"v":"Een vergelijking met x kwadraat. Om welk begrip gaat het?","o":["Exact rekenen","Kwadratische vergelijking","Ontbinden in factoren","Herleiden"],"c":1,"d":1,"u":"Een vergelijking met x kwadraat. Dat past bij Kwadratische vergelijking: hoogste macht x².","uo":["Nee, dat hoort bij Exact rekenen: niet afronden.","Klopt: hoogste macht x².","Nee, dat hoort bij Ontbinden in factoren: som als product.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven."],"uh":"Kwadratische vergelijking: hoogste macht x²."},{"v":"Een uitdrukking eenvoudiger schrijven. Welk begrip herken je hier?","o":["Beginwaarde","Ontbinden in factoren","Herleiden","Exact rekenen"],"c":2,"d":3,"u":"Een uitdrukking eenvoudiger schrijven. Dat past bij Herleiden: eenvoudiger schrijven.","uo":["Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Nee, dat hoort bij Ontbinden in factoren: som als product.","Klopt: eenvoudiger schrijven.","Nee, dat hoort bij Exact rekenen: niet afronden."],"uh":"Herleiden: eenvoudiger schrijven."},{"v":"Je werkt de haakjes weg en schrijft het zo eenvoudig mogelijk. Wat is hier aan de hand?","o":["Exact rekenen","Substitutie","Beginwaarde","Herleiden"],"c":3,"d":1,"u":"Je werkt de haakjes weg en schrijft het zo eenvoudig mogelijk. Dat past bij Herleiden: eenvoudiger schrijven.","uo":["Nee, dat hoort bij Exact rekenen: niet afronden.","Nee, dat hoort bij Substitutie: invullen in de andere vergelijking.","Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Klopt: eenvoudiger schrijven."],"uh":"Herleiden: eenvoudiger schrijven."},{"v":"Twee vergelijkingen met een gemeenschappelijke oplossing. Welk begrip past hierbij?","o":["Stelsel vergelijkingen","Substitutie","Richtingscoëfficiënt","Herleiden"],"c":0,"d":3,"u":"Twee vergelijkingen met een gemeenschappelijke oplossing. Dat past bij Stelsel vergelijkingen: twee vergelijkingen samen.","uo":["Klopt: twee vergelijkingen samen.","Nee, dat hoort bij Substitutie: invullen in de andere vergelijking.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven."],"uh":"Stelsel vergelijkingen: twee vergelijkingen samen."},{"v":"Twee vergelijkingen die je samen oplost voor x en y. Om welk begrip gaat het?","o":["Richtingscoëfficiënt","Stelsel vergelijkingen","Beginwaarde","Discriminant"],"c":1,"d":1,"u":"Twee vergelijkingen die je samen oplost voor x en y. Dat past bij Stelsel vergelijkingen: twee vergelijkingen samen.","uo":["Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Klopt: twee vergelijkingen samen.","Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Nee, dat hoort bij Discriminant: b² − 4ac."],"uh":"Stelsel vergelijkingen: twee vergelijkingen samen."},{"v":"Een variabele uitdrukken en invullen. Welk begrip herken je hier?","o":["Richtingscoëfficiënt","Stelsel vergelijkingen","Substitutie","Kwadratische vergelijking"],"c":2,"d":3,"u":"Een variabele uitdrukken en invullen. Dat past bij Substitutie: invullen in de andere vergelijking.","uo":["Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Klopt: invullen in de andere vergelijking.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x²."],"uh":"Substitutie: invullen in de andere vergelijking."},{"v":"Doorrekenen zonder af te ronden. Wat is hier aan de hand?","o":["Stelsel vergelijkingen","Substitutie","Richtingscoëfficiënt","Exact rekenen"],"c":3,"d":1,"u":"Doorrekenen zonder af te ronden. Dat past bij Exact rekenen: niet afronden.","uo":["Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Nee, dat hoort bij Substitutie: invullen in de andere vergelijking.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Klopt: niet afronden."],"uh":"Exact rekenen: niet afronden."},{"v":"De startwaarde van een verband. Welk begrip past hierbij?","o":["Beginwaarde","Richtingscoëfficiënt","Stelsel vergelijkingen","Kwadratische vergelijking"],"c":0,"d":3,"u":"De startwaarde van een verband. Dat past bij Beginwaarde: waarde bij x = 0.","uo":["Klopt: waarde bij x = 0.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x²."],"uh":"Beginwaarde: waarde bij x = 0."},{"v":"Een vergelijking waarin x kwadraat de hoogste macht is. Om welk begrip gaat het?","o":["Exact rekenen","Kwadratische vergelijking","Ontbinden in factoren","Herleiden"],"c":1,"d":1,"u":"Een vergelijking waarin x kwadraat de hoogste macht is. Dat past bij Kwadratische vergelijking: hoogste macht x².","uo":["Nee, dat hoort bij Exact rekenen: niet afronden.","Klopt: hoogste macht x².","Nee, dat hoort bij Ontbinden in factoren: som als product.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven."],"uh":"Kwadratische vergelijking: hoogste macht x²."},{"v":"Een verband met een rechte lijn. Welk begrip herken je hier?","o":["Discriminant","Kwadratische vergelijking","Lineair verband","Substitutie"],"c":2,"d":3,"u":"Een verband met een rechte lijn. Dat past bij Lineair verband: rechte lijn.","uo":["Nee, dat hoort bij Discriminant: b² − 4ac.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x².","Klopt: rechte lijn.","Nee, dat hoort bij Substitutie: invullen in de andere vergelijking."],"uh":"Lineair verband: rechte lijn."},{"v":"De a in y is ax plus b. Wat is hier aan de hand?","o":["Stelsel vergelijkingen","Exact rekenen","Herleiden","Richtingscoëfficiënt"],"c":3,"d":1,"u":"De a in y is ax plus b. Dat past bij Richtingscoëfficiënt: helling Δy/Δx.","uo":["Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Nee, dat hoort bij Exact rekenen: niet afronden.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven.","Klopt: helling Δy/Δx."],"uh":"Richtingscoëfficiënt: helling Δy/Δx."},{"v":"De waarde die je op de y-as afleest als x nul is. Welk begrip past hierbij?","o":["Beginwaarde","Richtingscoëfficiënt","Exact rekenen","Kwadratische vergelijking"],"c":0,"d":2,"u":"De waarde die je op de y-as afleest als x nul is. Dat past bij Beginwaarde: waarde bij x = 0.","uo":["Klopt: waarde bij x = 0.","Nee, dat hoort bij Richtingscoëfficiënt: helling Δy/Δx.","Nee, dat hoort bij Exact rekenen: niet afronden.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x²."],"uh":"Beginwaarde: waarde bij x = 0."},{"v":"De helling: hoeveel y stijgt als x met 1 toeneemt. Om welk begrip gaat het?","o":["Beginwaarde","Richtingscoëfficiënt","Stelsel vergelijkingen","Lineair verband"],"c":1,"d":3,"u":"De helling: hoeveel y stijgt als x met 1 toeneemt. Dat past bij Richtingscoëfficiënt: helling Δy/Δx.","uo":["Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Klopt: helling Δy/Δx.","Nee, dat hoort bij Stelsel vergelijkingen: twee vergelijkingen samen.","Nee, dat hoort bij Lineair verband: rechte lijn."],"uh":"Richtingscoëfficiënt: helling Δy/Δx."},{"v":"Je drukt y uit in x en vult dat in de andere vergelijking in. Welk begrip herken je hier?","o":["Exact rekenen","Beginwaarde","Substitutie","Kwadratische vergelijking"],"c":2,"d":1,"u":"Je drukt y uit in x en vult dat in de andere vergelijking in. Dat past bij Substitutie: invullen in de andere vergelijking.","uo":["Nee, dat hoort bij Exact rekenen: niet afronden.","Nee, dat hoort bij Beginwaarde: waarde bij x = 0.","Klopt: invullen in de andere vergelijking.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x²."],"uh":"Substitutie: invullen in de andere vergelijking."},{"v":"Je laat wortels en breuken staan in plaats van af te ronden. Wat is hier aan de hand?","o":["Lineair verband","Herleiden","Kwadratische vergelijking","Exact rekenen"],"c":3,"d":2,"u":"Je laat wortels en breuken staan in plaats van af te ronden. Dat past bij Exact rekenen: niet afronden.","uo":["Nee, dat hoort bij Lineair verband: rechte lijn.","Nee, dat hoort bij Herleiden: eenvoudiger schrijven.","Nee, dat hoort bij Kwadratische vergelijking: hoogste macht x².","Klopt: niet afronden."],"uh":"Exact rekenen: niet afronden."}],"oe":[{"bron":"HAVO Wiskunde B CE 2022 Tijdvak 1 Modelleren met een stelsel (geen afbeelding)","ctx":"Een sporthal verhuurt twee typen zalen: kleine zalen (A) voor €60 per uur en grote zalen (B) voor €110 per uur. Op een dag zijn er in totaal 14 uur aan verhuur geboekt voor een totale opbrengst van €1120.","v":"(a) Stel een stelsel van twee vergelijkingen op in a (uren kleine zaal) en b (uren grote zaal).\n(b) Los het stelsel algebraïsch op via substitutie en bereken hoeveel uur elke zaalttype is verhuurd.\n(c) De eigenaar wil weten of het winstgevend is om de kleine zalen te vervangen door extra grote zalen. De vaste kosten stijgen dan met €200 per dag. Bereken hoeveel uur grote zalen dan minimaal verhuurd moeten worden om de dagopbrengst gelijk te houden.","o":[""],"c":0,"u":"(a) a + b = 14 en 60a + 110b = 1120.\n(b) Uit (1): a = 14 − b. Invullen: 60(14 − b) + 110b = 1120 → 840 − 60b + 110b = 1120 → 50b = 280 → b = 5,6 uur. a = 14 − 5,6 = 8,4 uur.\n(c) Huidige opbrengst = €1120. Nieuwe situatie: alle uren via grote zalen, vaste kosten +€200. Minimale opbrengst = 1120 + 200 = €1320. Benodigde uren grote zaal: 110 · t = 1320 → t = 12 uur. Er moeten minimaal 12 uur grote zalen worden verhuurd."},{"bron":"HAVO Wiskunde B CE 2023 Tijdvak 2 Exponentieel model en domein (geen afbeelding)","ctx":"Een batterij verliest elke uur 18% van de resterende lading. Bij t = 0 is de lading 100%.","v":"(a) Stel een formule op voor de lading L (in %) na t uur.\n(b) Bereken na hoeveel uur de lading onder de 20% daalt. Rond af op één decimaal.\n(c) Een fabrikant claimt: \"Na 10 uur is de batterij leeg (L = 0%).\" Beoordeel deze uitspraak wiskundig en geef aan of het model dit ondersteunt.","o":[""],"c":0,"u":"(a) L(t) = 100 · 0,82^t.\n(b) 100 · 0,82^t < 20 → 0,82^t < 0,2. Logaritmeer: t > log(0,2)/log(0,82) = −0,699/−0,086 ≈ 8,1 uur. Na 8,1 uur daalt de lading onder de 20%.\n(c) L(10) = 100 · 0,82^10 ≈ 100 · 0,137 = 13,7% - dus niet 0%. Wiskundig nadert L(t) = 0 alleen als t → ∞: de exponentiële functie bereikt nooit exact nul. De uitspraak van de fabrikant klopt niet: het model voorspelt nooit L = 0. In de praktijk wordt een batterij als \"leeg\" beschouwd bij bijv. 5% of 10%, maar het model steunt de claim van nul niet."},{"bron":"HAVO Wiskunde B CE 2022 Tijdvak 2 Stelsel vergelijkingen (geen afbeelding)","ctx":"Een school verkoopt kaartjes voor een voorstelling. Gewone kaartjes kosten €8 en VIP-kaartjes kosten €15. Er worden in totaal 120 kaartjes verkocht voor een totaalbedrag van €1240.","v":"(a) Stel een stelsel van twee vergelijkingen op met g (gewone) en v (VIP-kaartjes).\n(b) Los het stelsel op met de substitutiemethode.\n(c) Bereken de totale opbrengst van uitsluitend de VIP-kaartjes.","o":[""],"c":0,"u":"(a) g + v = 120 en 8g + 15v = 1240.\n(b) Uit (1): g = 120 − v. Invullen in (2): 8(120 − v) + 15v = 1240 → 960 − 8v + 15v = 1240 → 7v = 280 → v = 40. Dan g = 120 − 40 = 80.\n(c) Opbrengst VIP = 40 × €15 = €600."}],"begrippen":[{"t":"Beginwaarde","d":"de waarde die je op de y-as afleest bij x = 0"},{"t":"Lineair verband","d":"een verband met een rechte lijn en een constante stijging"},{"t":"Substitutie","d":"één variabele uitdrukken en invullen in de andere vergelijking"},{"t":"Stelsel vergelijkingen","d":"twee vergelijkingen met een gemeenschappelijke oplossing"},{"t":"Richtingscoëfficiënt","d":"de helling Δy/Δx van een rechte lijn"},{"t":"Herleiden","d":"een uitdrukking zo eenvoudig mogelijk schrijven"},{"t":"Kwadratische vergelijking","d":"een vergelijking met x² als hoogste macht"},{"t":"Discriminant","d":"D = b² − 4ac, bepaalt het aantal reële oplossingen"},{"t":"Ontbinden in factoren","d":"een som als product van factoren schrijven"},{"t":"Exact rekenen","d":"met breuken en wortels doorrekenen zonder af te ronden"}],"sam":"<div class=\"sam-intro\">De basis van wiskunde B: <strong>herleiden</strong>, <strong>vergelijkingen oplossen</strong> en <strong>ontbinden in factoren</strong>. Je leest de <strong>beginwaarde</strong> en <strong>richtingscoëfficiënt</strong> af, en lost een <strong>stelsel vergelijkingen</strong> op met <strong>substitutie</strong>.</div><div class=\"sam-head\">1. Algebra</div><p><strong>Herleiden</strong> is een uitdrukking eenvoudiger schrijven, bijvoorbeeld (x − 1)(x + 1) = x² − 1. <strong>Ontbinden in factoren</strong> schrijft een som als product: x² − 9 = (x − 3)(x + 3). Een <strong>vergelijking</strong> los je op door aan beide kanten dezelfde bewerking te doen; x² = 16 geeft x = ±4.</p><div class=\"sam-head\">2. Grafieken en stelsels</div><p>Bij x = 0 lees je op de y-as de <strong>beginwaarde</strong> af. Een <strong>lineair verband</strong> is een rechte lijn met een constante <strong>richtingscoëfficiënt</strong> (Δy/Δx). Een <strong>stelsel vergelijkingen</strong> los je op met <strong>substitutie</strong>: druk één variabele uit en vul die in de andere vergelijking in.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Beginwaarde</div><div class=\"sam-definitie-body\">de waarde die je op de y-as afleest bij x = 0.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lineair verband</div><div class=\"sam-definitie-body\">een verband met een rechte lijn en een constante stijging.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Substitutie</div><div class=\"sam-definitie-body\">één variabele uitdrukken en invullen in de andere vergelijking.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stelsel vergelijkingen</div><div class=\"sam-definitie-body\">twee vergelijkingen met een gemeenschappelijke oplossing.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Richtingscoëfficiënt</div><div class=\"sam-definitie-body\">de helling Δy/Δx van een rechte lijn.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Herleiden</div><div class=\"sam-definitie-body\">een uitdrukking zo eenvoudig mogelijk schrijven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kwadratische vergelijking</div><div class=\"sam-definitie-body\">een vergelijking met x² als hoogste macht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Discriminant</div><div class=\"sam-definitie-body\">D = b² − 4ac, bepaalt het aantal reële oplossingen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontbinden in factoren</div><div class=\"sam-definitie-body\">een som als product van factoren schrijven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Exact rekenen</div><div class=\"sam-definitie-body\">met breuken en wortels doorrekenen zonder af te ronden.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Beginwaarde»</b> is waarde bij x = 0, terwijl <b>«Richtingscoëfficiënt»</b> helling Δy/Δx is. <b>«Lineair verband»</b> is rechte lijn, terwijl <b>«Kwadratische vergelijking»</b> hoogste macht x² is. <b>«Substitutie»</b> is invullen in de andere vergelijking, terwijl <b>«Stelsel vergelijkingen»</b> twee vergelijkingen samen is. <b>«Herleiden»</b> is eenvoudiger schrijven, terwijl <b>«Ontbinden in factoren»</b> som als product is.</div>"},"B":{"sv":[{"v":"Wat is een functie in de wiskunde?","o":["een verband dat aan elke x precies één y toekent","een verband met meerdere y per x","een willekeurige verzameling punten","een rechte lijn"],"c":0,"d":2,"u":"Elke x heeft precies één y.","uo":["Klopt: elke x heeft precies één y.","Nee, dan is het geen functie.","Nee, er moet een regel zijn.","Nee, dat is maar één soort functie."],"uh":"Functie: elke x geeft precies één y."},{"v":"Hoe verschuift f(x − 3) ten opzichte van f(x)?","o":["3 naar links","3 naar rechts","3 omhoog","3 omlaag"],"c":1,"d":3,"u":"F(x − c) schuift c naar rechts.","uo":["Nee, dat is f(x + 3).","Klopt: f(x − c) schuift c naar rechts.","Nee, dat is f(x) + 3.","Nee, dat is f(x) − 3."],"uh":"f(x − c) met c > 0: c naar rechts."},{"v":"Wat is de horizontale asymptoot van f(x) = 3·2ˣ + 1?","o":["y = 0","y = 3","y = 1","y = 2"],"c":2,"d":3,"u":"De plus 1 tilt de asymptoot naar y = 1.","uo":["Nee, zonder de plus 1 was het y = 0.","Nee, 3 is de factor voor de macht.","Klopt: de plus 1 tilt de asymptoot naar y = 1.","Nee, 2 is het grondtal."],"uh":"De constante term bepaalt de horizontale asymptoot."},{"v":"Hoe los je een exponentiële vergelijking op?","o":["deel door x","kwadrateer beide kanten","tel bij beide kanten op","logaritmeer beide kanten"],"c":3,"d":3,"u":"Met de logaritme haal je x uit de exponent.","uo":["Nee, dat helpt niet.","Nee, dat helpt hier niet.","Nee, dat lost het niet op.","Klopt: met de logaritme haal je x uit de exponent."],"uh":"Exponentiële vergelijking: logaritmeer beide kanten."},{"v":"Welke transformatie geeft −f(x) op de grafiek?","o":["een spiegeling in de x-as","een spiegeling in de y-as","een verschuiving naar links","een verschuiving omhoog"],"c":0,"d":3,"u":"Het minteken spiegelt in de x-as.","uo":["Klopt: het minteken spiegelt in de x-as.","Nee, dat is f(−x).","Nee, dat is een translatie.","Nee, dat is f(x) + c."],"uh":"−f(x): spiegeling in de x-as."},{"v":"Hoe vind je de snijpunten van twee grafieken f en g?","o":["tel f en g op","stel f(x) = g(x) en los op","trek f van g af en stop","teken alleen f"],"c":1,"d":2,"u":"Op een snijpunt zijn de y-waarden gelijk.","uo":["Nee, dat geeft geen snijpunt.","Klopt: op een snijpunt zijn de y-waarden gelijk.","Nee, je moet de vergelijking oplossen.","Nee, dan mis je g."],"uh":"Snijpunten: los f(x) = g(x) op."},{"v":"Wat is de amplitude van y = 4·sin(x) + 1?","o":["5","1","4 (de factor voor de sinus)","2π"],"c":2,"d":2,"u":"De factor 4 is de amplitude.","uo":["Nee, dat is 4 + 1, geen amplitude.","Nee, dat is de verticale verschuiving.","Klopt: de factor 4 is de amplitude.","Nee, dat is een periode."],"uh":"In a·sin(bx) is |a| de amplitude."},{"v":"Wat is de periode van y = sin(3x)?","o":["π","2π","3","2π/3"],"c":3,"d":3,"u":"Periode = 2π/b = 2π/3.","uo":["Nee, deel 2π door 3.","Nee, dat is de periode van sin(x).","Nee, 3 is de factor b.","Klopt: periode = 2π/b = 2π/3."],"uh":"Periode van sin(bx): 2π/b."},{"v":"Wat doet de transformatie f(x) + 2 met de grafiek?","o":["ze schuift 2 omhoog","ze schuift 2 naar rechts","ze spiegelt in de x-as","ze wordt smaller"],"c":0,"d":2,"u":"Bij de functiewaarde optellen schuift verticaal.","uo":["Klopt: bij de functiewaarde optellen schuift verticaal.","Nee, dat is f(x − 2).","Nee, dat is −f(x).","Nee, dat is een vervorming."],"uh":"f(x) + c met c > 0: c omhoog."},{"v":"Wat is het domein van een functie?","o":["de mogelijke y-waarden","de toegestane x-waarden","de nulpunten","de asymptoten"],"c":1,"d":2,"u":"Het domein zijn de toegestane invoerwaarden.","uo":["Nee, dat is het bereik.","Klopt: het domein zijn de toegestane invoerwaarden.","Nee, dat zijn losse punten.","Nee, dat zijn lijnen."],"uh":"Domein: de toegestane x-waarden."},{"v":"Wat is het bereik van een functie?","o":["het aantal nulpunten","de toegestane x-waarden","de mogelijke y-waarden","de periode"],"c":2,"d":2,"u":"Het bereik zijn de mogelijke uitkomsten.","uo":["Nee, dat is een aantal.","Nee, dat is het domein.","Klopt: het bereik zijn de mogelijke uitkomsten.","Nee, dat is een lengte."],"uh":"Bereik: de mogelijke y-waarden."},{"v":"Los op: 2ˣ = 8.","o":["x = 8","x = 4","x = 2","x = 3"],"c":3,"d":2,"u":"Het juiste antwoord is: x = 3.","uo":["Nee, x is de exponent, niet het getal.","Nee, 2⁴ = 16.","Nee, 2² = 4.","Klopt: 2³ = 8."],"uh":"Schrijf beide kanten als macht van hetzelfde grondtal."},{"v":"Je verschuift of spiegelt de grafiek van een functie. Welk begrip past hierbij?","o":["Transformatie","Amplitude","Snijpunt","Periode"],"c":0,"d":1,"u":"Je verschuift of spiegelt de grafiek van een functie. Dat past bij Transformatie: grafiek bewerken.","uo":["Klopt: grafiek bewerken.","Nee, dat hoort bij Amplitude: uitwijking |a|.","Nee, dat hoort bij Snijpunt: f(x) = g(x).","Nee, dat hoort bij Periode: 2π/b."],"uh":"Transformatie: grafiek bewerken."},{"v":"De transformatie min f van x spiegelt de grafiek in de x-as. Om welk begrip gaat het?","o":["Amplitude","Spiegeling","Bereik","Asymptoot"],"c":1,"d":1,"u":"De transformatie min f van x spiegelt de grafiek in de x-as. Dat past bij Spiegeling: spiegelen in de x-as.","uo":["Nee, dat hoort bij Amplitude: uitwijking |a|.","Klopt: spiegelen in de x-as.","Nee, dat hoort bij Bereik: mogelijke y-waarden.","Nee, dat hoort bij Asymptoot: lijn die grafiek nadert."],"uh":"Spiegeling: spiegelen in de x-as."},{"v":"Spiegelen in de x-as. Welk begrip herken je hier?","o":["Bereik","Amplitude","Spiegeling","Asymptoot"],"c":2,"d":1,"u":"Spiegelen in de x-as. Dat past bij Spiegeling: spiegelen in de x-as.","uo":["Nee, dat hoort bij Bereik: mogelijke y-waarden.","Nee, dat hoort bij Amplitude: uitwijking |a|.","Klopt: spiegelen in de x-as.","Nee, dat hoort bij Asymptoot: lijn die grafiek nadert."],"uh":"Spiegeling: spiegelen in de x-as."},{"v":"De toegestane invoerwaarden. Wat is hier aan de hand?","o":["Functie","Snijpunt","Spiegeling","Domein"],"c":3,"d":1,"u":"De toegestane invoerwaarden. Dat past bij Domein: toegestane x-waarden.","uo":["Nee, dat hoort bij Functie: elke x geeft één y.","Nee, dat hoort bij Snijpunt: f(x) = g(x).","Nee, dat hoort bij Spiegeling: spiegelen in de x-as.","Klopt: toegestane x-waarden."],"uh":"Domein: toegestane x-waarden."},{"v":"Alle x-waarden die je in de functie mag invullen. Welk begrip past hierbij?","o":["Domein","Snijpunt","Spiegeling","Functie"],"c":0,"d":1,"u":"Alle x-waarden die je in de functie mag invullen. Dat past bij Domein: toegestane x-waarden.","uo":["Klopt: toegestane x-waarden.","Nee, dat hoort bij Snijpunt: f(x) = g(x).","Nee, dat hoort bij Spiegeling: spiegelen in de x-as.","Nee, dat hoort bij Functie: elke x geeft één y."],"uh":"Domein: toegestane x-waarden."},{"v":"Waar f en g elkaar snijden, uit f is g. Om welk begrip gaat het?","o":["Functie","Snijpunt","Amplitude","Domein"],"c":1,"d":1,"u":"Waar f en g elkaar snijden, uit f is g. Dat past bij Snijpunt: f(x) = g(x).","uo":["Nee, dat hoort bij Functie: elke x geeft één y.","Klopt: f(x) = g(x).","Nee, dat hoort bij Amplitude: uitwijking |a|.","Nee, dat hoort bij Domein: toegestane x-waarden."],"uh":"Snijpunt: f(x) = g(x)."},{"v":"De herhaallengte van een sinus. Welk begrip herken je hier?","o":["Asymptoot","Amplitude","Periode","Functie"],"c":2,"d":3,"u":"De herhaallengte van een sinus. Dat past bij Periode: 2π/b.","uo":["Nee, dat hoort bij Asymptoot: lijn die grafiek nadert.","Nee, dat hoort bij Amplitude: uitwijking |a|.","Klopt: 2π/b.","Nee, dat hoort bij Functie: elke x geeft één y."],"uh":"Periode: 2π/b."},{"v":"Na hoeveel de sinusgrafiek zich herhaalt, 2 pi gedeeld door b. Wat is hier aan de hand?","o":["Bereik","Snijpunt","Spiegeling","Periode"],"c":3,"d":1,"u":"Na hoeveel de sinusgrafiek zich herhaalt, 2 pi gedeeld door b. Dat past bij Periode: 2π/b.","uo":["Nee, dat hoort bij Bereik: mogelijke y-waarden.","Nee, dat hoort bij Snijpunt: f(x) = g(x).","Nee, dat hoort bij Spiegeling: spiegelen in de x-as.","Klopt: 2π/b."],"uh":"Periode: 2π/b."},{"v":"Een vergelijking met de onbekende in de exponent. Welk begrip past hierbij?","o":["Exponentiële vergelijking","Amplitude","Domein","Snijpunt"],"c":0,"d":3,"u":"Een vergelijking met de onbekende in de exponent. Dat past bij Exponentiële vergelijking: x in de exponent.","uo":["Klopt: x in de exponent.","Nee, dat hoort bij Amplitude: uitwijking |a|.","Nee, dat hoort bij Domein: toegestane x-waarden.","Nee, dat hoort bij Snijpunt: f(x) = g(x)."],"uh":"Exponentiële vergelijking: x in de exponent."},{"v":"In 2 tot de macht x is 8 staat de onbekende in de exponent. Om welk begrip gaat het?","o":["Bereik","Exponentiële vergelijking","Domein","Snijpunt"],"c":1,"d":1,"u":"In 2 tot de macht x is 8 staat de onbekende in de exponent. Dat past bij Exponentiële vergelijking: x in de exponent.","uo":["Nee, dat hoort bij Bereik: mogelijke y-waarden.","Klopt: x in de exponent.","Nee, dat hoort bij Domein: toegestane x-waarden.","Nee, dat hoort bij Snijpunt: f(x) = g(x)."],"uh":"Exponentiële vergelijking: x in de exponent."},{"v":"Een lijn die de grafiek nadert. Welk begrip herken je hier?","o":["Exponentiële vergelijking","Periode","Asymptoot","Snijpunt"],"c":2,"d":2,"u":"Een lijn die de grafiek nadert. Dat past bij Asymptoot: lijn die grafiek nadert.","uo":["Nee, dat hoort bij Exponentiële vergelijking: x in de exponent.","Nee, dat hoort bij Periode: 2π/b.","Klopt: lijn die grafiek nadert.","Nee, dat hoort bij Snijpunt: f(x) = g(x)."],"uh":"Asymptoot: lijn die grafiek nadert."},{"v":"De mogelijke uitkomsten. Wat is hier aan de hand?","o":["Exponentiële vergelijking","Domein","Functie","Bereik"],"c":3,"d":3,"u":"De mogelijke uitkomsten. Dat past bij Bereik: mogelijke y-waarden.","uo":["Nee, dat hoort bij Exponentiële vergelijking: x in de exponent.","Nee, dat hoort bij Domein: toegestane x-waarden.","Nee, dat hoort bij Functie: elke x geeft één y.","Klopt: mogelijke y-waarden."],"uh":"Bereik: mogelijke y-waarden."},{"v":"Een verband dat aan elke x één y toekent. Welk begrip past hierbij?","o":["Functie","Snijpunt","Spiegeling","Bereik"],"c":0,"d":1,"u":"Een verband dat aan elke x één y toekent. Dat past bij Functie: elke x geeft één y.","uo":["Klopt: elke x geeft één y.","Nee, dat hoort bij Snijpunt: f(x) = g(x).","Nee, dat hoort bij Spiegeling: spiegelen in de x-as.","Nee, dat hoort bij Bereik: mogelijke y-waarden."],"uh":"Functie: elke x geeft één y."},{"v":"Het punt waar twee grafieken elkaar kruisen. Om welk begrip gaat het?","o":["Asymptoot","Snijpunt","Exponentiële vergelijking","Periode"],"c":1,"d":2,"u":"Het punt waar twee grafieken elkaar kruisen. Dat past bij Snijpunt: f(x) = g(x).","uo":["Nee, dat hoort bij Asymptoot: lijn die grafiek nadert.","Klopt: f(x) = g(x).","Nee, dat hoort bij Exponentiële vergelijking: x in de exponent.","Nee, dat hoort bij Periode: 2π/b."],"uh":"Snijpunt: f(x) = g(x)."},{"v":"Een bewerking van een grafiek. Welk begrip herken je hier?","o":["Bereik","Functie","Transformatie","Snijpunt"],"c":2,"d":3,"u":"Een bewerking van een grafiek. Dat past bij Transformatie: grafiek bewerken.","uo":["Nee, dat hoort bij Bereik: mogelijke y-waarden.","Nee, dat hoort bij Functie: elke x geeft één y.","Klopt: grafiek bewerken.","Nee, dat hoort bij Snijpunt: f(x) = g(x)."],"uh":"Transformatie: grafiek bewerken."},{"v":"De factor a voor de sinus. Wat is hier aan de hand?","o":["Bereik","Asymptoot","Functie","Amplitude"],"c":3,"d":1,"u":"De factor a voor de sinus. Dat past bij Amplitude: uitwijking |a|.","uo":["Nee, dat hoort bij Bereik: mogelijke y-waarden.","Nee, dat hoort bij Asymptoot: lijn die grafiek nadert.","Nee, dat hoort bij Functie: elke x geeft één y.","Klopt: uitwijking |a|."],"uh":"Amplitude: uitwijking |a|."},{"v":"Bij elke invoer x hoort precies één uitkomst y. Welk begrip past hierbij?","o":["Functie","Transformatie","Asymptoot","Bereik"],"c":0,"d":2,"u":"Bij elke invoer x hoort precies één uitkomst y. Dat past bij Functie: elke x geeft één y.","uo":["Klopt: elke x geeft één y.","Nee, dat hoort bij Transformatie: grafiek bewerken.","Nee, dat hoort bij Asymptoot: lijn die grafiek nadert.","Nee, dat hoort bij Bereik: mogelijke y-waarden."],"uh":"Functie: elke x geeft één y."},{"v":"Hoe ver een sinusgolf maximaal van het midden uitwijkt. Om welk begrip gaat het?","o":["Periode","Amplitude","Functie","Bereik"],"c":1,"d":3,"u":"Hoe ver een sinusgolf maximaal van het midden uitwijkt. Dat past bij Amplitude: uitwijking |a|.","uo":["Nee, dat hoort bij Periode: 2π/b.","Klopt: uitwijking |a|.","Nee, dat hoort bij Functie: elke x geeft één y.","Nee, dat hoort bij Bereik: mogelijke y-waarden."],"uh":"Amplitude: uitwijking |a|."},{"v":"De grafiek nadert deze lijn steeds dichter zonder hem te raken. Welk begrip herken je hier?","o":["Functie","Exponentiële vergelijking","Asymptoot","Bereik"],"c":2,"d":1,"u":"De grafiek nadert deze lijn steeds dichter zonder hem te raken. Dat past bij Asymptoot: lijn die grafiek nadert.","uo":["Nee, dat hoort bij Functie: elke x geeft één y.","Nee, dat hoort bij Exponentiële vergelijking: x in de exponent.","Klopt: lijn die grafiek nadert.","Nee, dat hoort bij Bereik: mogelijke y-waarden."],"uh":"Asymptoot: lijn die grafiek nadert."},{"v":"Alle y-waarden die de functie kan aannemen. Wat is hier aan de hand?","o":["Spiegeling","Domein","Exponentiële vergelijking","Bereik"],"c":3,"d":2,"u":"Alle y-waarden die de functie kan aannemen. Dat past bij Bereik: mogelijke y-waarden.","uo":["Nee, dat hoort bij Spiegeling: spiegelen in de x-as.","Nee, dat hoort bij Domein: toegestane x-waarden.","Nee, dat hoort bij Exponentiële vergelijking: x in de exponent.","Klopt: mogelijke y-waarden."],"uh":"Bereik: mogelijke y-waarden."}],"oe":[{"bron":"HAVO Wiskunde B CE 2021 Tijdvak 2 Transformaties en asymptoot (geen afbeelding)","ctx":"Gegeven f(x) = 3^x. Functie g ontstaat uit f door: eerst horizontaal met factor ½ comprimeren, dan 4 omhoog verschuiven. Functie h ontstaat uit f door: spiegelen in de y-as en daarna 1 naar links verschuiven.","v":"(a) Geef de formules van g(x) en h(x).\n(b) Bepaal de horizontale asymptoot van g en de horizontale asymptoot van h.\n(c) Bereken het snijpunt van g met de y-as en het snijpunt van h met de y-as.","o":[""],"c":0,"u":"(a) Horizontale compressie met factor ½: f(2x) = 3^(2x). Dan 4 omhoog: g(x) = 3^(2x) + 4. Spiegelen in y-as: f(−x) = 3^(−x). Dan 1 naar links (x vervangen door x+1): h(x) = 3^(−(x+1)) = 3^(−x−1).\n(b) g(x): als x → −∞ daalt 3^(2x) → 0, dus g(x) → 4. Asymptoot: y = 4. h(x): als x → +∞ daalt 3^(−x−1) → 0, dus h(x) → 0. Asymptoot: y = 0.\n(c) g(0) = 3^0 + 4 = 1 + 4 = 5. Snijpunt g met y-as: (0, 5). h(0) = 3^(−1) = ⅓. Snijpunt h met y-as: (0, ⅓)."},{"bron":"HAVO Wiskunde B CE 2024 Tijdvak 1 Snijpunten en ongelijkheid (geen afbeelding)","ctx":"Gegeven f(x) = −x² + 4x + 12 en g(x) = 2x + 4.","v":"(a) Bepaal de nulpunten van f algebraïsch.\n(b) Bereken de coördinaten van de snijpunten van f en g.\n(c) Voor welke x-waarden geldt f(x) ≥ g(x)? Geef het antwoord als interval en verklaar de aanpak via een tekenschema.","o":[""],"c":0,"u":"(a) −x² + 4x + 12 = 0 → x² − 4x − 12 = 0 → (x − 6)(x + 2) = 0. Nulpunten: x = 6 en x = −2.\n(b) Stel f(x) = g(x): −x² + 4x + 12 = 2x + 4 → −x² + 2x + 8 = 0 → x² − 2x − 8 = 0 → (x − 4)(x + 2) = 0. x = 4 of x = −2. Coördinaten: bij x = 4: g(4) = 12 → (4, 12). Bij x = −2: g(−2) = 0 → (−2, 0).\n(c) f(x) ≥ g(x) ↔ f(x) − g(x) ≥ 0 ↔ −x² + 2x + 8 ≥ 0 ↔ x² − 2x − 8 ≤ 0 ↔ (x − 4)(x + 2) ≤ 0. Tekenschema: nulpunten bij x = −2 en x = 4. Voor x < −2: beide factoren negatief → product positief (> 0, voldoet niet). Voor −2 ≤ x ≤ 4: factoren hebben tegengesteld teken → product negatief of nul (≤ 0, voldoet). Voor x > 4: beide positief → product positief (voldoet niet). Antwoord: −2 ≤ x ≤ 4."},{"bron":"HAVO Wiskunde B CE 2023 Tijdvak 1 Exponentiële afname (geen afbeelding)","ctx":"De waarde W (in euro) van een auto neemt na aankoop exponentieel af. Op tijdstip t = 0 is de auto €25.000 waard. Na 5 jaar is de waarde gedaald naar €12.500.","v":"(a) Bereken de afnamefactor per jaar.\n(b) Geef een formule voor W als functie van t (in jaren).\n(c) Na hoeveel jaar is de auto minder dan €5.000 waard?","o":[""],"c":0,"u":"(a) W(5) = 25000 · g^5 = 12500 → g^5 = 0,5 → g = 0,5^(1/5) ≈ 0,871.\n(b) W(t) = 25000 · 0,871^t.\n(c) 25000 · 0,871^t < 5000 → 0,871^t < 0,2. Logaritmeer: t · log(0,871) < log(0,2) → t > log(0,2)/log(0,871) ≈ 11,6. Na 12 jaar is de auto minder dan €5.000 waard."}],"begrippen":[{"t":"Functie","d":"een verband dat aan elke x precies één y toekent"},{"t":"Transformatie","d":"een verschuiving, spiegeling of vervorming van een grafiek"},{"t":"Asymptoot","d":"een lijn die de grafiek steeds dichter nadert zonder te raken"},{"t":"Exponentiële vergelijking","d":"een vergelijking met de onbekende in de exponent"},{"t":"Amplitude","d":"de uitwijking |a| van een sinusfunctie a·sin(bx)"},{"t":"Periode","d":"de lengte 2π/b waarna een sinusfunctie zich herhaalt"},{"t":"Snijpunt","d":"een punt waar twee grafieken elkaar kruisen, uit f(x) = g(x)"},{"t":"Spiegeling","d":"de transformatie −f(x): spiegelen in de x-as"},{"t":"Domein","d":"de verzameling toegestane x-waarden van een functie"},{"t":"Bereik","d":"de verzameling mogelijke y-waarden van een functie"}],"sam":"<div class=\"sam-intro\">Een <strong>functie</strong> geeft bij elke x precies één y. Met <strong>transformaties</strong> verschuif, spiegel of vervorm je een grafiek. Een <strong>asymptoot</strong> nadert de grafiek zonder te raken. <strong>Exponentiële</strong> en <strong>goniometrische</strong> functies hebben eigen kenmerken zoals <strong>periode</strong> en <strong>amplitude</strong>.</div><div class=\"sam-head\">1. Functies en transformaties</div><p>Een <strong>functie</strong> koppelt aan elke x precies één y. <strong>Transformaties</strong>: f(x − c) verschuift c naar rechts, f(x) + c omhoog, en −f(x) is een <strong>spiegeling</strong> in de x-as. <strong>Snijpunten</strong> van f en g vind je door f(x) = g(x) op te lossen. Het <strong>domein</strong> zijn de toegestane x-waarden, het <strong>bereik</strong> de mogelijke y-waarden.</p><div class=\"sam-head\">2. Exponentieel en goniometrie</div><p>Een <strong>exponentiële vergelijking</strong> los je op door te <strong>logaritmeren</strong>. De <strong>horizontale asymptoot</strong> van f(x) = 3·2ˣ + 1 is y = 1. Voor een <strong>sinusfunctie</strong> y = a·sin(bx): de <strong>amplitude</strong> is |a| en de <strong>periode</strong> is 2π/b.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Functie</div><div class=\"sam-definitie-body\">een verband dat aan elke x precies één y toekent.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Transformatie</div><div class=\"sam-definitie-body\">een verschuiving, spiegeling of vervorming van een grafiek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Asymptoot</div><div class=\"sam-definitie-body\">een lijn die de grafiek steeds dichter nadert zonder te raken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Exponentiële vergelijking</div><div class=\"sam-definitie-body\">een vergelijking met de onbekende in de exponent.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Amplitude</div><div class=\"sam-definitie-body\">de uitwijking |a| van een sinusfunctie a·sin(bx).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Periode</div><div class=\"sam-definitie-body\">de lengte 2π/b waarna een sinusfunctie zich herhaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Snijpunt</div><div class=\"sam-definitie-body\">een punt waar twee grafieken elkaar kruisen, uit f(x) = g(x).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Spiegeling</div><div class=\"sam-definitie-body\">de transformatie −f(x): spiegelen in de x-as.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Domein</div><div class=\"sam-definitie-body\">de verzameling toegestane x-waarden van een functie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bereik</div><div class=\"sam-definitie-body\">de verzameling mogelijke y-waarden van een functie.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Functie»</b> is elke x geeft één y, terwijl <b>«Transformatie»</b> grafiek bewerken is. <b>«Asymptoot»</b> is lijn die grafiek nadert, terwijl <b>«Periode»</b> 2π/b is. <b>«Exponentiële vergelijking»</b> is x in de exponent, terwijl <b>«Amplitude»</b> uitwijking |a| is. <b>«Amplitude»</b> is uitwijking |a|, terwijl <b>«Periode»</b> 2π/b is.</div>"},"C":{"sv":[{"v":"Wanneer zijn twee vectoren loodrecht op elkaar?","o":["als het inproduct 0 is","als ze even lang zijn","als hun som 0 is","als ze parallel zijn"],"c":0,"d":3,"u":"Loodrecht betekent inproduct 0.","uo":["Klopt: loodrecht betekent inproduct 0.","Nee, gelijke lengte zegt niets over de hoek.","Nee, dat betekent tegengesteld.","Nee, parallel is juist niet loodrecht."],"uh":"Loodrechte vectoren: inproduct gelijk aan 0."},{"v":"Wat is de helling van een loodlijn op een lijn met rc = 2?","o":["2","−½","½","−2"],"c":1,"d":3,"u":"Rc₁·rc₂ = −1, dus −½.","uo":["Nee, dat is dezelfde helling.","Klopt: rc₁·rc₂ = −1, dus −½.","Nee, dat product is niet −1.","Nee, dat product is niet −1."],"uh":"Loodrecht: het product van de rc's is −1."},{"v":"Wat betekent het als het inproduct van twee vectoren nul is?","o":["de vectoren zijn parallel","de vectoren zijn even lang","de vectoren staan loodrecht op elkaar","een van de vectoren is nul"],"c":2,"d":2,"u":"Inproduct 0 betekent een hoek van 90°.","uo":["Nee, parallel geeft juist geen 0.","Nee, dat volgt er niet uit.","Klopt: inproduct 0 betekent een hoek van 90°.","Nee, dat hoeft niet."],"uh":"Inproduct 0: de vectoren staan loodrecht."},{"v":"Wat beschrijft sin α in een rechthoekige driehoek?","o":["schuinzijde gedeeld door overstaande","aanliggende gedeeld door schuinzijde","overstaande gedeeld door aanliggende","overstaande gedeeld door schuinzijde"],"c":3,"d":2,"u":"Sin = overstaande/schuinzijde.","uo":["Nee, dat is het omgekeerde.","Nee, dat is de cosinus.","Nee, dat is de tangens.","Klopt: sin = overstaande/schuinzijde."],"uh":"SOH: sin = overstaande / schuinzijde."},{"v":"Wanneer gebruik je de sinusregel?","o":["bij twee hoeken en een zijde, of twee zijden met een overstaande hoek","alleen bij een rechthoekige driehoek","bij drie gegeven zijden","nooit"],"c":0,"d":3,"u":"De sinusregel past bij deze gevallen.","uo":["Klopt: de sinusregel past bij deze gevallen.","Nee, dan volstaat SOH-CAH-TOA.","Nee, dan gebruik je de cosinusregel.","Nee, hij is vaak nodig."],"uh":"Sinusregel: bij twee hoeken en een zijde (of AAS/ASA)."},{"v":"Hoe controleer je of punt P op de cirkel (x − 2)² + (y − 3)² = 25 ligt?","o":["kijk of P in het middelpunt ligt","vul P in en vergelijk de uitkomst met 25","bereken de rc van P","tel de coördinaten van P op"],"c":1,"d":3,"u":"Als invullen 25 geeft, ligt P op de cirkel.","uo":["Nee, dat is het middelpunt, niet de rand.","Klopt: als invullen 25 geeft, ligt P op de cirkel.","Nee, dat is niet relevant.","Nee, dat zegt niets."],"uh":"Punt op cirkel: invullen en vergelijken met r²."},{"v":"Wat beschrijft cos α in een rechthoekige driehoek?","o":["overstaande gedeeld door aanliggende","overstaande gedeeld door schuinzijde","aanliggende gedeeld door schuinzijde","schuinzijde gedeeld door aanliggende"],"c":2,"d":2,"u":"Cos = aanliggende/schuinzijde.","uo":["Nee, dat is de tangens.","Nee, dat is de sinus.","Klopt: cos = aanliggende/schuinzijde.","Nee, dat is het omgekeerde."],"uh":"CAH: cos = aanliggende / schuinzijde."},{"v":"Wat beschrijft tan α in een rechthoekige driehoek?","o":["schuinzijde gedeeld door overstaande","overstaande gedeeld door schuinzijde","aanliggende gedeeld door schuinzijde","overstaande gedeeld door aanliggende"],"c":3,"d":2,"u":"Tan = overstaande/aanliggende.","uo":["Nee, dat is het omgekeerde.","Nee, dat is de sinus.","Nee, dat is de cosinus.","Klopt: tan = overstaande/aanliggende."],"uh":"TOA: tan = overstaande / aanliggende."},{"v":"Wanneer gebruik je de cosinusregel?","o":["bij drie zijden, of twee zijden met de ingesloten hoek","alleen bij twee hoeken","alleen in een rechthoekige driehoek","nooit"],"c":0,"d":3,"u":"De cosinusregel past bij deze gevallen.","uo":["Klopt: de cosinusregel past bij deze gevallen.","Nee, dan gebruik je de sinusregel.","Nee, dan volstaat SOH-CAH-TOA.","Nee, hij is vaak nodig."],"uh":"Cosinusregel: drie zijden of twee zijden met ingesloten hoek."},{"v":"Hoe controleer je of twee lijnen loodrecht op elkaar staan?","o":["ze hebben dezelfde rc","het product van hun richtingscoëfficiënten is −1","hun som is 0","ze snijden de y-as"],"c":1,"d":3,"u":"Rc₁·rc₂ = −1.","uo":["Nee, dan zijn ze evenwijdig.","Klopt: rc₁·rc₂ = −1.","Nee, dat klopt niet.","Nee, dat zegt niets over loodrecht."],"uh":"Twee lijnen loodrecht: rc₁ × rc₂ = −1."},{"v":"Waar staat SOH-CAH-TOA voor?","o":["de drie zijden van een driehoek","sin = A/H, cos = O/H, tan = A/O","sin = O/H, cos = A/H, tan = O/A","de oppervlakte van een driehoek"],"c":2,"d":2,"u":"Dat is het ezelsbruggetje.","uo":["Nee, het gaat over verhoudingen.","Nee, dat is verwisseld.","Klopt: dat is het ezelsbruggetje.","Nee, het gaat niet over oppervlakte."],"uh":"SOH-CAH-TOA: sin=O/H, cos=A/H, tan=O/A."},{"v":"Wat is een vector?","o":["een hoek","alleen een getal","een punt in het vlak","een grootheid met een grootte en een richting"],"c":3,"d":2,"u":"Een vector heeft grootte en richting.","uo":["Nee, dat is iets anders.","Nee, een getal heeft geen richting.","Nee, een punt heeft geen richting.","Klopt: een vector heeft grootte en richting."],"uh":"Vector: grootheid met grootte en richting."},{"v":"Twee vectoren waarvan het inproduct nul is. Welk begrip past hierbij?","o":["Loodrecht","Cosinus","Inproduct","Vector"],"c":0,"d":1,"u":"Twee vectoren waarvan het inproduct nul is. Dat past bij Loodrecht: inproduct 0.","uo":["Klopt: inproduct 0.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Inproduct: som van producten van kentallen.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Loodrecht: inproduct 0."},{"v":"Bij drie zijden of twee zijden met de ingesloten hoek. Om welk begrip gaat het?","o":["Richtingscoëfficiënt loodlijn","Cosinusregel","Cosinus","Vector"],"c":1,"d":1,"u":"Bij drie zijden of twee zijden met de ingesloten hoek. Dat past bij Cosinusregel: drie zijden of ingesloten hoek.","uo":["Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1.","Klopt: drie zijden of ingesloten hoek.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Cosinusregel: drie zijden of ingesloten hoek."},{"v":"De regel bij drie zijden of een ingesloten hoek. Welk begrip herken je hier?","o":["Cosinus","Richtingscoëfficiënt loodlijn","Cosinusregel","Vector"],"c":2,"d":1,"u":"De regel bij drie zijden of een ingesloten hoek. Dat past bij Cosinusregel: drie zijden of ingesloten hoek.","uo":["Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1.","Klopt: drie zijden of ingesloten hoek.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Cosinusregel: drie zijden of ingesloten hoek."},{"v":"De standaardvorm van een cirkel. Wat is hier aan de hand?","o":["Sinusregel","Vector","Loodrecht","Cirkelvergelijking"],"c":3,"d":1,"u":"De standaardvorm van een cirkel. Dat past bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","uo":["Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Loodrecht: inproduct 0.","Klopt: (x − a)² + (y − b)² = r²."],"uh":"Cirkelvergelijking: (x − a)² + (y − b)² = r²."},{"v":"De vorm x min a in het kwadraat plus y min b in het kwadraat is r kwadraat. Welk begrip past hierbij?","o":["Cirkelvergelijking","Vector","Loodrecht","Sinusregel"],"c":0,"d":1,"u":"De vorm x min a in het kwadraat plus y min b in het kwadraat is r kwadraat. Dat past bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","uo":["Klopt: (x − a)² + (y − b)² = r².","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Loodrecht: inproduct 0.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B."],"uh":"Cirkelvergelijking: (x − a)² + (y − b)² = r²."},{"v":"De regel a/sin A is b/sin B. Om welk begrip gaat het?","o":["Sinus","Sinusregel","Vector","Loodrecht"],"c":1,"d":1,"u":"De regel a/sin A is b/sin B. Dat past bij Sinusregel: a/sin A = b/sin B.","uo":["Nee, dat hoort bij Sinus: overstaande / schuinzijde.","Klopt: a/sin A = b/sin B.","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Loodrecht: inproduct 0."],"uh":"Sinusregel: a/sin A = b/sin B."},{"v":"Overstaande gedeeld door aanliggende. Welk begrip herken je hier?","o":["Cosinusregel","Sinusregel","Tangens","Vector"],"c":2,"d":1,"u":"Overstaande gedeeld door aanliggende. Dat past bij Tangens: overstaande / aanliggende.","uo":["Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Klopt: overstaande / aanliggende.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Tangens: overstaande / aanliggende."},{"v":"In een rechthoekige driehoek de overstaande gedeeld door de aanliggende. Wat is hier aan de hand?","o":["Vector","Sinus","Inproduct","Tangens"],"c":3,"d":2,"u":"In een rechthoekige driehoek de overstaande gedeeld door de aanliggende. Dat past bij Tangens: overstaande / aanliggende.","uo":["Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Sinus: overstaande / schuinzijde.","Nee, dat hoort bij Inproduct: som van producten van kentallen.","Klopt: overstaande / aanliggende."],"uh":"Tangens: overstaande / aanliggende."},{"v":"Overstaande gedeeld door schuinzijde. Welk begrip past hierbij?","o":["Sinus","Cosinus","Sinusregel","Cosinusregel"],"c":0,"d":3,"u":"Overstaande gedeeld door schuinzijde. Dat past bij Sinus: overstaande / schuinzijde.","uo":["Klopt: overstaande / schuinzijde.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek."],"uh":"Sinus: overstaande / schuinzijde."},{"v":"In een rechthoekige driehoek de overstaande gedeeld door de schuinzijde. Om welk begrip gaat het?","o":["Tangens","Sinus","Richtingscoëfficiënt loodlijn","Cirkelvergelijking"],"c":1,"d":1,"u":"In een rechthoekige driehoek de overstaande gedeeld door de schuinzijde. Dat past bij Sinus: overstaande / schuinzijde.","uo":["Nee, dat hoort bij Tangens: overstaande / aanliggende.","Klopt: overstaande / schuinzijde.","Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1.","Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r²."],"uh":"Sinus: overstaande / schuinzijde."},{"v":"De loodlijn heeft product min een met de rc. Welk begrip herken je hier?","o":["Sinus","Loodrecht","Richtingscoëfficiënt loodlijn","Cirkelvergelijking"],"c":2,"d":2,"u":"De loodlijn heeft product min een met de rc. Dat past bij Richtingscoëfficiënt loodlijn: rc met product −1.","uo":["Nee, dat hoort bij Sinus: overstaande / schuinzijde.","Nee, dat hoort bij Loodrecht: inproduct 0.","Klopt: rc met product −1.","Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r²."],"uh":"Richtingscoëfficiënt loodlijn: rc met product −1."},{"v":"Een grootheid met grootte en richting. Wat is hier aan de hand?","o":["Cosinus","Inproduct","Loodrecht","Vector"],"c":3,"d":3,"u":"Een grootheid met grootte en richting. Dat past bij Vector: grootte en richting.","uo":["Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Inproduct: som van producten van kentallen.","Nee, dat hoort bij Loodrecht: inproduct 0.","Klopt: grootte en richting."],"uh":"Vector: grootte en richting."},{"v":"De som van de producten van de kentallen. Welk begrip past hierbij?","o":["Inproduct","Cosinus","Richtingscoëfficiënt loodlijn","Vector"],"c":0,"d":1,"u":"De som van de producten van de kentallen. Dat past bij Inproduct: som van producten van kentallen.","uo":["Klopt: som van producten van kentallen.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Inproduct: som van producten van kentallen."},{"v":"Bij twee hoeken en een zijde reken je met a gedeeld door sin A. Om welk begrip gaat het?","o":["Cosinusregel","Sinusregel","Cosinus","Richtingscoëfficiënt loodlijn"],"c":1,"d":2,"u":"Bij twee hoeken en een zijde reken je met a gedeeld door sin A. Dat past bij Sinusregel: a/sin A = b/sin B.","uo":["Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek.","Klopt: a/sin A = b/sin B.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1."],"uh":"Sinusregel: a/sin A = b/sin B."},{"v":"Ze staan haaks op elkaar. Welk begrip herken je hier?","o":["Inproduct","Sinus","Loodrecht","Vector"],"c":2,"d":3,"u":"Ze staan haaks op elkaar. Dat past bij Loodrecht: inproduct 0.","uo":["Nee, dat hoort bij Inproduct: som van producten van kentallen.","Nee, dat hoort bij Sinus: overstaande / schuinzijde.","Klopt: inproduct 0.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Loodrecht: inproduct 0."},{"v":"Aanliggende gedeeld door schuinzijde. Wat is hier aan de hand?","o":["Vector","Sinusregel","Cosinusregel","Cosinus"],"c":3,"d":1,"u":"Aanliggende gedeeld door schuinzijde. Dat past bij Cosinus: aanliggende / schuinzijde.","uo":["Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek.","Klopt: aanliggende / schuinzijde."],"uh":"Cosinus: aanliggende / schuinzijde."},{"v":"Je vermenigvuldigt de kentallen en telt op; nul betekent loodrecht. Welk begrip past hierbij?","o":["Inproduct","Loodrecht","Cosinus","Sinusregel"],"c":0,"d":2,"u":"Je vermenigvuldigt de kentallen en telt op; nul betekent loodrecht. Dat past bij Inproduct: som van producten van kentallen.","uo":["Klopt: som van producten van kentallen.","Nee, dat hoort bij Loodrecht: inproduct 0.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B."],"uh":"Inproduct: som van producten van kentallen."},{"v":"In een rechthoekige driehoek de aanliggende gedeeld door de schuinzijde. Om welk begrip gaat het?","o":["Sinus","Cosinus","Richtingscoëfficiënt loodlijn","Inproduct"],"c":1,"d":3,"u":"In een rechthoekige driehoek de aanliggende gedeeld door de schuinzijde. Dat past bij Cosinus: aanliggende / schuinzijde.","uo":["Nee, dat hoort bij Sinus: overstaande / schuinzijde.","Klopt: aanliggende / schuinzijde.","Nee, dat hoort bij Richtingscoëfficiënt loodlijn: rc met product −1.","Nee, dat hoort bij Inproduct: som van producten van kentallen."],"uh":"Cosinus: aanliggende / schuinzijde."},{"v":"De helling waarvan het product met de gegeven helling min een is. Welk begrip herken je hier?","o":["Sinusregel","Vector","Richtingscoëfficiënt loodlijn","Cosinusregel"],"c":2,"d":1,"u":"De helling waarvan het product met de gegeven helling min een is. Dat past bij Richtingscoëfficiënt loodlijn: rc met product −1.","uo":["Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Vector: grootte en richting.","Klopt: rc met product −1.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek."],"uh":"Richtingscoëfficiënt loodlijn: rc met product −1."},{"v":"Een pijl met een grootte en een richting. Wat is hier aan de hand?","o":["Cirkelvergelijking","Inproduct","Cosinus","Vector"],"c":3,"d":2,"u":"Een pijl met een grootte en een richting. Dat past bij Vector: grootte en richting.","uo":["Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","Nee, dat hoort bij Inproduct: som van producten van kentallen.","Nee, dat hoort bij Cosinus: aanliggende / schuinzijde.","Klopt: grootte en richting."],"uh":"Vector: grootte en richting."}],"oe":[{"bron":"HAVO Wiskunde B CE 2022 Tijdvak 2 Vectoren, loodrechtheid en hoekberekening (geen afbeelding)","ctx":"In een coördinatenstelsel zijn de punten A(1, 3), B(5, 1) en C(4, 6) gegeven.","v":"(a) Bepaal de vectoren →AB en →AC.\n(b) Bereken het inwendig product →AB · →AC en de grootte van beide vectoren.\n(c) Bereken de hoek BAC in graden (afronden op één decimaal).","o":[""],"c":0,"u":"(a) →AB = B − A = (5−1, 1−3) = (4, −2). →AC = C − A = (4−1, 6−3) = (3, 3).\n(b) →AB · →AC = 4·3 + (−2)·3 = 12 − 6 = 6. |→AB| = √(16 + 4) = √20 = 2√5. |→AC| = √(9 + 9) = √18 = 3√2.\n(c) cos(∠BAC) = (→AB · →AC) / (|→AB| · |→AC|) = 6 / (2√5 · 3√2) = 6 / (6√10) = 1/√10. ∠BAC = arccos(1/√10) ≈ arccos(0,3162) ≈ 71,6°."},{"bron":"HAVO Wiskunde B CE 2023 Tijdvak 1 Sinusregel, cosinusregel en oppervlakte (geen afbeelding)","ctx":"Een landmeter meet een driehoekig perceel PQR. De zijde PQ = 80 m, de zijde PR = 65 m en de hoek bij P (hoek QPR) = 48°.","v":"(a) Bereken de lengte van QR met de cosinusregel. Rond af op één decimaal.\n(b) Bereken de oppervlakte van het perceel in m². Rond af op gehele getallen.\n(c) De eigenaar wil een hek plaatsen langs de gehele omtrek van het perceel. Bereken de totale omtrek.","o":[""],"c":0,"u":"(a) QR² = PQ² + PR² − 2·PQ·PR·cos(P) = 6400 + 4225 − 2·80·65·cos(48°) = 10625 − 10400·0,6691 = 10625 − 6958,6 = 3666,4. QR = √3666,4 ≈ 60,6 m.\n(b) Opp = ½·PQ·PR·sin(P) = ½·80·65·sin(48°) = 2600·0,7431 ≈ 1932 m².\n(c) Omtrek = PQ + PR + QR = 80 + 65 + 60,6 = 205,6 m ≈ 206 m."},{"bron":"HAVO Wiskunde B CE 2024 Tijdvak 2 Cirkel en lijn (geen afbeelding)","ctx":"Gegeven de cirkel C: (x − 3)² + (y + 1)² = 25 en de lijn l: y = 2x − 5.","v":"(a) Geef het middelpunt en de straal van cirkel C.\n(b) Bereken algebraïsch de snijpunten van l en C.\n(c) Ligt punt P(6, 2) op, binnen of buiten de cirkel? Onderbouw met een berekening.","o":[""],"c":0,"u":"(a) Middelpunt M(3, −1), straal r = 5.\n(b) Substitueer y = 2x − 5 in de cirkelvergelijking: (x−3)² + (2x−5+1)² = 25 → (x−3)² + (2x−4)² = 25 → x²−6x+9 + 4x²−16x+16 = 25 → 5x²−22x = 0 → x(5x−22) = 0 → x = 0 of x = 4,4. Bij x = 0: y = −5. Bij x = 4,4: y = 3,8. Snijpunten: (0, −5) en (4,4; 3,8).\n(c) (6−3)² + (2+1)² = 9 + 9 = 18 < 25 → P ligt binnen de cirkel."}],"begrippen":[{"t":"Inproduct","d":"a₁b₁ + a₂b₂; is 0 bij loodrechte vectoren"},{"t":"Loodrecht","d":"twee vectoren met inproduct 0, of lijnen met rc₁·rc₂ = −1"},{"t":"Richtingscoëfficiënt loodlijn","d":"de rc waarvan het product met de gegeven rc gelijk aan −1 is"},{"t":"Sinus","d":"in een rechthoekige driehoek: overstaande gedeeld door schuinzijde"},{"t":"Cosinus","d":"in een rechthoekige driehoek: aanliggende gedeeld door schuinzijde"},{"t":"Tangens","d":"in een rechthoekige driehoek: overstaande gedeeld door aanliggende"},{"t":"Sinusregel","d":"a/sin A = b/sin B, bij twee hoeken en een zijde"},{"t":"Cosinusregel","d":"de regel bij drie zijden of twee zijden met de ingesloten hoek"},{"t":"Cirkelvergelijking","d":"de standaardvorm (x − a)² + (y − b)² = r²"},{"t":"Vector","d":"een grootheid met een grootte en een richting"}],"sam":"<div class=\"sam-intro\">Met <strong>vectoren</strong> en het <strong>inproduct</strong> bepaal je of lijnen <strong>loodrecht</strong> staan (inproduct 0). In een rechthoekige driehoek gebruik je <strong>sinus</strong>, <strong>cosinus</strong> en <strong>tangens</strong> (SOH-CAH-TOA), en bij andere driehoeken de <strong>sinus-</strong> of <strong>cosinusregel</strong>. Een <strong>cirkel</strong> heeft de vergelijking (x − a)² + (y − b)² = r².</div><div class=\"sam-head\">1. Vectoren en loodrecht</div><p>Twee vectoren staan <strong>loodrecht</strong> als hun <strong>inproduct</strong> nul is. Twee lijnen staan loodrecht als het product van hun richtingscoëfficiënten −1 is; de loodlijn op rc = 2 heeft rc = −½.</p><div class=\"sam-head\">2. Driehoeken en cirkels</div><p>In een rechthoekige driehoek geldt <strong>SOH-CAH-TOA</strong>: sin = overstaande/schuinzijde, cos = aanliggende/schuinzijde, tan = overstaande/aanliggende. De <strong>sinusregel</strong> gebruik je bij twee hoeken en een zijde; de <strong>cosinusregel</strong> bij drie zijden of twee zijden met de ingesloten hoek. Een punt ligt op de <strong>cirkel</strong> (x − a)² + (y − b)² = r² als invullen r² geeft.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inproduct</div><div class=\"sam-definitie-body\">a₁b₁ + a₂b₂; is 0 bij loodrechte vectoren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Loodrecht</div><div class=\"sam-definitie-body\">twee vectoren met inproduct 0, of lijnen met rc₁·rc₂ = −1.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Richtingscoëfficiënt loodlijn</div><div class=\"sam-definitie-body\">de rc waarvan het product met de gegeven rc gelijk aan −1 is.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sinus</div><div class=\"sam-definitie-body\">in een rechthoekige driehoek: overstaande gedeeld door schuinzijde.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cosinus</div><div class=\"sam-definitie-body\">in een rechthoekige driehoek: aanliggende gedeeld door schuinzijde.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Tangens</div><div class=\"sam-definitie-body\">in een rechthoekige driehoek: overstaande gedeeld door aanliggende.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sinusregel</div><div class=\"sam-definitie-body\">a/sin A = b/sin B, bij twee hoeken en een zijde.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cosinusregel</div><div class=\"sam-definitie-body\">de regel bij drie zijden of twee zijden met de ingesloten hoek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cirkelvergelijking</div><div class=\"sam-definitie-body\">de standaardvorm (x − a)² + (y − b)² = r².</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vector</div><div class=\"sam-definitie-body\">een grootheid met een grootte en een richting.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Inproduct»</b> is som van producten van kentallen, terwijl <b>«Loodrecht»</b> inproduct 0 is. <b>«Loodrecht»</b> is inproduct 0, terwijl <b>«Sinus»</b> overstaande / schuinzijde is. <b>«Richtingscoëfficiënt loodlijn»</b> is rc met product −1, terwijl <b>«Loodrecht»</b> inproduct 0 is. <b>«Sinus»</b> is overstaande / schuinzijde, terwijl <b>«Cosinus»</b> aanliggende / schuinzijde is.</div>"},"D":{"sv":[{"v":"Wat is de vergelijking van de raaklijn aan f(x) in het punt x = a?","o":["y = f'(a)·(x − a) + f(a)","y = f(a)·x","y = f'(x)·a","y = a·x + b"],"c":0,"d":3,"u":"Helling f'(a), gaat door (a, f(a)).","uo":["Klopt: helling f'(a), gaat door (a, f(a)).","Nee, dat is geen raaklijn.","Nee, dat klopt niet.","Nee, dat is een algemene lijn."],"uh":"Raaklijn: y = f'(a)·(x − a) + f(a)."},{"v":"Wat is de kettingregel?","o":["f'(x)·g'(x)","[f(g(x))]' = f'(g(x))·g'(x)","f'(x) + g'(x)","f(x)·g(x)"],"c":1,"d":3,"u":"Buitenste differentiëren maal de afgeleide van de binnenste.","uo":["Nee, dat is niet de kettingregel.","Klopt: buitenste differentiëren maal de afgeleide van de binnenste.","Nee, dat klopt niet.","Nee, dat is een gewoon product."],"uh":"Kettingregel: f'(g(x))·g'(x)."},{"v":"Wat is de afgeleide van de constante functie f(x) = 5?","o":["1","5","0","5x"],"c":2,"d":1,"u":"Een constante verandert niet, dus afgeleide 0.","uo":["Nee, de helling is 0.","Nee, de functiewaarde is 5, de helling 0.","Klopt: een constante verandert niet, dus afgeleide 0.","Nee, er is geen x."],"uh":"De afgeleide van een constante is 0."},{"v":"Wat is de afgeleide van sin(x)?","o":["tan(x)","−cos(x)","−sin(x)","cos(x)"],"c":3,"d":2,"u":"De afgeleide van sin(x) is cos(x).","uo":["Nee, dat is een andere functie.","Nee, het teken klopt niet.","Nee, dat is de vorm van de afgeleide van cos.","Klopt: de afgeleide van sin(x) is cos(x)."],"uh":"De afgeleide van sin(x) is cos(x)."},{"v":"Wat is de afgeleide van f(x) = ln(x)?","o":["1/x","ln(x)","x","eˣ"],"c":0,"d":2,"u":"De afgeleide van ln(x) is 1/x.","uo":["Klopt: de afgeleide van ln(x) is 1/x.","Nee, dat is de functie zelf.","Nee, dat klopt niet.","Nee, dat is een andere functie."],"uh":"De afgeleide van ln(x) is 1/x."},{"v":"Wat is de afgeleide van f(x) = x²?","o":["x","2x","2","x³"],"c":1,"d":2,"u":"N·xⁿ⁻¹ geeft 2x.","uo":["Nee, de exponent komt ervoor.","Klopt: n·xⁿ⁻¹ geeft 2x.","Nee, de x blijft staan.","Nee, dat zou integreren zijn."],"uh":"De afgeleide van x² is 2x."},{"v":"Wat is de afgeleide van f(x) = x³?","o":["3x","x²","3x²","3x³"],"c":2,"d":2,"u":"3·x² volgens n·xⁿ⁻¹.","uo":["Nee, de exponent wordt 2.","Nee, de factor 3 hoort ervoor.","Klopt: 3·x² volgens n·xⁿ⁻¹.","Nee, de exponent daalt met 1."],"uh":"De afgeleide van x³ is 3x²."},{"v":"Welke regel gebruik je voor de afgeleide van f(x) = x²·sin(x)?","o":["de wortelregel","de kettingregel","geen regel","de productregel"],"c":3,"d":3,"u":"Het is een product van twee functies.","uo":["Nee, die bestaat niet.","Nee, er is geen samenstelling f(g(x)).","Nee, een regel is nodig.","Klopt: het is een product van twee functies."],"uh":"Product van functies: de productregel."},{"v":"Wat geldt als f'(x) > 0 op een interval?","o":["de functie stijgt daar","de functie daalt daar","de functie is constant","er ligt een minimum"],"c":0,"d":2,"u":"Een positieve afgeleide betekent stijgen.","uo":["Klopt: een positieve afgeleide betekent stijgen.","Nee, dalen hoort bij f'(x) < 0.","Nee, constant hoort bij f'(x) = 0.","Nee, een minimum is één punt."],"uh":"f'(x) > 0: de functie stijgt."},{"v":"Waar heeft een functie een extremum?","o":["waar f(x) = 0","waar f'(x) = 0 en het teken omslaat","waar f'(x) het grootst is","waar de grafiek de y-as snijdt"],"c":1,"d":2,"u":"In een top of dal is de helling 0.","uo":["Nee, dat is een nulpunt van f.","Klopt: in een top of dal is de helling 0.","Nee, dat is de steilste helling.","Nee, dat is het y-snijpunt."],"uh":"Extremum: f'(x) = 0 met tekenwissel."},{"v":"Wat is de afgeleide van f(x) = cos(x)?","o":["cos(x)","sin(x)","−sin(x)","−cos(x)"],"c":2,"d":2,"u":"De afgeleide van cos(x) is −sin(x).","uo":["Nee, dat is de functie zelf.","Nee, let op het minteken.","Klopt: de afgeleide van cos(x) is −sin(x).","Nee, dat klopt niet."],"uh":"De afgeleide van cos(x) is −sin(x)."},{"v":"Wat is de afgeleide van f(x) = eˣ?","o":["ln(x)","x·eˣ⁻¹","1","eˣ"],"c":3,"d":2,"u":"Eˣ is zijn eigen afgeleide.","uo":["Nee, dat is de omgekeerde functie.","Nee, dat is de machtsregel.","Nee, de afgeleide is niet constant.","Klopt: eˣ is zijn eigen afgeleide."],"uh":"De afgeleide van eˣ is eˣ."},{"v":"De lijn die de grafiek in precies één punt raakt. Welk begrip past hierbij?","o":["Raaklijn","Afgeleide","Extremum","Stationair punt"],"c":0,"d":1,"u":"De lijn die de grafiek in precies één punt raakt. Dat past bij Raaklijn: raakt in één punt.","uo":["Klopt: raakt in één punt.","Nee, dat hoort bij Afgeleide: helling in elk punt.","Nee, dat hoort bij Extremum: top of dal.","Nee, dat hoort bij Stationair punt: f'(x) = 0."],"uh":"Raaklijn: raakt in één punt."},{"v":"Het punt waar de grafiek van hol naar bol overgaat. Om welk begrip gaat het?","o":["Afgeleide","Buigpunt","Productregel","Stationair punt"],"c":1,"d":1,"u":"Het punt waar de grafiek van hol naar bol overgaat. Dat past bij Buigpunt: f''(x) = 0.","uo":["Nee, dat hoort bij Afgeleide: helling in elk punt.","Klopt: f''(x) = 0.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Stationair punt: f'(x) = 0."],"uh":"Buigpunt: f''(x) = 0."},{"v":"Waar de tweede afgeleide nul is. Welk begrip herken je hier?","o":["Productregel","Afgeleide","Buigpunt","Stationair punt"],"c":2,"d":1,"u":"Waar de tweede afgeleide nul is. Dat past bij Buigpunt: f''(x) = 0.","uo":["Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Afgeleide: helling in elk punt.","Klopt: f''(x) = 0.","Nee, dat hoort bij Stationair punt: f'(x) = 0."],"uh":"Buigpunt: f''(x) = 0."},{"v":"Waar de afgeleide gelijk is aan nul. Wat is hier aan de hand?","o":["Raaklijn","Buigpunt","Helling","Stationair punt"],"c":3,"d":3,"u":"Waar de afgeleide gelijk is aan nul. Dat past bij Stationair punt: f'(x) = 0.","uo":["Nee, dat hoort bij Raaklijn: raakt in één punt.","Nee, dat hoort bij Buigpunt: f''(x) = 0.","Nee, dat hoort bij Helling: steilheid.","Klopt: f'(x) = 0."],"uh":"Stationair punt: f'(x) = 0."},{"v":"Een punt waar de helling nul is. Welk begrip past hierbij?","o":["Stationair punt","Differentiëren","Extremum","Kettingregel"],"c":0,"d":1,"u":"Een punt waar de helling nul is. Dat past bij Stationair punt: f'(x) = 0.","uo":["Klopt: f'(x) = 0.","Nee, dat hoort bij Differentiëren: de afgeleide bepalen.","Nee, dat hoort bij Extremum: top of dal.","Nee, dat hoort bij Kettingregel: voor f(g(x))."],"uh":"Stationair punt: f'(x) = 0."},{"v":"Het omgekeerde van differentiëren. Om welk begrip gaat het?","o":["Afgeleide","Primitieve","Productregel","Helling"],"c":1,"d":3,"u":"Het omgekeerde van differentiëren. Dat past bij Primitieve: omgekeerde van afgeleide.","uo":["Nee, dat hoort bij Afgeleide: helling in elk punt.","Klopt: omgekeerde van afgeleide.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Helling: steilheid."],"uh":"Primitieve: omgekeerde van afgeleide."},{"v":"De steilheid van de raaklijn. Welk begrip herken je hier?","o":["Buigpunt","Primitieve","Helling","Differentiëren"],"c":2,"d":1,"u":"De steilheid van de raaklijn. Dat past bij Helling: steilheid.","uo":["Nee, dat hoort bij Buigpunt: f''(x) = 0.","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Klopt: steilheid.","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Helling: steilheid."},{"v":"Hoe steil de grafiek in een punt loopt. Wat is hier aan de hand?","o":["Afgeleide","Raaklijn","Productregel","Helling"],"c":3,"d":3,"u":"Hoe steil de grafiek in een punt loopt. Dat past bij Helling: steilheid.","uo":["Nee, dat hoort bij Afgeleide: helling in elk punt.","Nee, dat hoort bij Raaklijn: raakt in één punt.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Klopt: steilheid."],"uh":"Helling: steilheid."},{"v":"De regel voor f keer g. Welk begrip past hierbij?","o":["Productregel","Extremum","Primitieve","Differentiëren"],"c":0,"d":1,"u":"De regel voor f keer g. Dat past bij Productregel: voor f(x)·g(x).","uo":["Klopt: voor f(x)·g(x).","Nee, dat hoort bij Extremum: top of dal.","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Productregel: voor f(x)·g(x)."},{"v":"Je differentieert een product van twee functies, zoals x kwadraat maal sin x. Om welk begrip gaat het?","o":["Kettingregel","Productregel","Primitieve","Extremum"],"c":1,"d":3,"u":"Je differentieert een product van twee functies, zoals x kwadraat maal sin x. Dat past bij Productregel: voor f(x)·g(x).","uo":["Nee, dat hoort bij Kettingregel: voor f(g(x)).","Klopt: voor f(x)·g(x).","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Extremum: top of dal."],"uh":"Productregel: voor f(x)·g(x)."},{"v":"De regel voor een samengestelde functie. Welk begrip herken je hier?","o":["Primitieve","Extremum","Kettingregel","Differentiëren"],"c":2,"d":1,"u":"De regel voor een samengestelde functie. Dat past bij Kettingregel: voor f(g(x)).","uo":["Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Extremum: top of dal.","Klopt: voor f(g(x)).","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Kettingregel: voor f(g(x))."},{"v":"Het bepalen van de afgeleide. Wat is hier aan de hand?","o":["Raaklijn","Primitieve","Kettingregel","Differentiëren"],"c":3,"d":3,"u":"Het bepalen van de afgeleide. Dat past bij Differentiëren: de afgeleide bepalen.","uo":["Nee, dat hoort bij Raaklijn: raakt in één punt.","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Kettingregel: voor f(g(x)).","Klopt: de afgeleide bepalen."],"uh":"Differentiëren: de afgeleide bepalen."},{"v":"De hellingfunctie van f. Welk begrip past hierbij?","o":["Afgeleide","Productregel","Raaklijn","Differentiëren"],"c":0,"d":1,"u":"De hellingfunctie van f. Dat past bij Afgeleide: helling in elk punt.","uo":["Klopt: helling in elk punt.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Raaklijn: raakt in één punt.","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Afgeleide: helling in elk punt."},{"v":"De functie waarvan de afgeleide je gegeven functie is. Om welk begrip gaat het?","o":["Afgeleide","Primitieve","Helling","Productregel"],"c":1,"d":2,"u":"De functie waarvan de afgeleide je gegeven functie is. Dat past bij Primitieve: omgekeerde van afgeleide.","uo":["Nee, dat hoort bij Afgeleide: helling in elk punt.","Klopt: omgekeerde van afgeleide.","Nee, dat hoort bij Helling: steilheid.","Nee, dat hoort bij Productregel: voor f(x)·g(x)."],"uh":"Primitieve: omgekeerde van afgeleide."},{"v":"De rechte met de afgeleide als helling. Welk begrip herken je hier?","o":["Extremum","Helling","Raaklijn","Differentiëren"],"c":2,"d":3,"u":"De rechte met de afgeleide als helling. Dat past bij Raaklijn: raakt in één punt.","uo":["Nee, dat hoort bij Extremum: top of dal.","Nee, dat hoort bij Helling: steilheid.","Klopt: raakt in één punt.","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Raaklijn: raakt in één punt."},{"v":"Een top of dal van de functie. Wat is hier aan de hand?","o":["Stationair punt","Afgeleide","Productregel","Extremum"],"c":3,"d":1,"u":"Een top of dal van de functie. Dat past bij Extremum: top of dal.","uo":["Nee, dat hoort bij Stationair punt: f'(x) = 0.","Nee, dat hoort bij Afgeleide: helling in elk punt.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Klopt: top of dal."],"uh":"Extremum: top of dal."},{"v":"De functie die in elk punt de helling geeft. Welk begrip past hierbij?","o":["Afgeleide","Primitieve","Productregel","Helling"],"c":0,"d":2,"u":"De functie die in elk punt de helling geeft. Dat past bij Afgeleide: helling in elk punt.","uo":["Klopt: helling in elk punt.","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Helling: steilheid."],"uh":"Afgeleide: helling in elk punt."},{"v":"De top of het dal waar de helling nul is. Om welk begrip gaat het?","o":["Helling","Extremum","Productregel","Differentiëren"],"c":1,"d":3,"u":"De top of het dal waar de helling nul is. Dat past bij Extremum: top of dal.","uo":["Nee, dat hoort bij Helling: steilheid.","Klopt: top of dal.","Nee, dat hoort bij Productregel: voor f(x)·g(x).","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Extremum: top of dal."},{"v":"Je differentieert een functie in een functie, zoals sin van x tot de derde. Welk begrip herken je hier?","o":["Primitieve","Extremum","Kettingregel","Differentiëren"],"c":2,"d":1,"u":"Je differentieert een functie in een functie, zoals sin van x tot de derde. Dat past bij Kettingregel: voor f(g(x)).","uo":["Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Extremum: top of dal.","Klopt: voor f(g(x)).","Nee, dat hoort bij Differentiëren: de afgeleide bepalen."],"uh":"Kettingregel: voor f(g(x))."},{"v":"Je bepaalt de afgeleide van een functie. Wat is hier aan de hand?","o":["Afgeleide","Primitieve","Stationair punt","Differentiëren"],"c":3,"d":2,"u":"Je bepaalt de afgeleide van een functie. Dat past bij Differentiëren: de afgeleide bepalen.","uo":["Nee, dat hoort bij Afgeleide: helling in elk punt.","Nee, dat hoort bij Primitieve: omgekeerde van afgeleide.","Nee, dat hoort bij Stationair punt: f'(x) = 0.","Klopt: de afgeleide bepalen."],"uh":"Differentiëren: de afgeleide bepalen."}],"oe":[{"bron":"HAVO Wiskunde B CE 2023 Tijdvak 1 (geen afbeelding)","ctx":"Gegeven f(x) = x tot de 3de min 6x² + 9x + 2.","v":"(a) Bereken f'(x).\n(b) Bepaal de extremen van f(x).\n(c) Bepaal het type (max/min) van elk extreem.","o":[""],"c":0,"u":"(a) f'(x) = 3x² min 12x + 9.\n(b) f'(x) = 0: 3x² min 12x + 9 = 0, dus x² min 4x + 3 = 0, (x-1)(x-3) = 0. Extremen bij x = 1 en x = 3.\n(c) f''(x) = 6x min 12. f''(1) = -6 kleiner dan 0: maximum. f''(3) = 6 groter dan 0: minimum. f(1) = 1-6+9+2 = 6 (max). f(3) = 27-54+27+2 = 2 (min)."},{"bron":"HAVO Wiskunde B CE 2022 Tijdvak 2 (geen afbeelding)","ctx":"Een boer wil een rechthoekig veld omheinen met 100 meter hek. Een muur dient als vierde zijde.","v":"(a) Stel een formule op voor de oppervlakte A als functie van de breedte x.\n(b) Bereken de afmetingen waarvoor de oppervlakte maximaal is.","o":[""],"c":0,"u":"(a) Hek: twee breedtes x en een lengte = 100 - 2x. A(x) = x(100-2x) = 100x - 2x².\n(b) A'(x) = 100 - 4x = 0 geeft x = 25. Lengte = 100 - 50 = 50. A''(x) = -4 kleiner dan 0: maximum. Maximale oppervlakte = 25·50 = 1250 m²."},{"bron":"HAVO Wiskunde B CE 2024 Tijdvak 1 (geen afbeelding)","ctx":"Gegeven f(x) = wortel(2x + 1) = (2x+1) tot de macht 1/2.","v":"(a) Bereken f'(x) met de kettingregel.\n(b) Bepaal de vergelijking van de raaklijn in x = 4.","o":[""],"c":0,"u":"(a) f(x) = (2x+1)^(1/2). Kettingregel: f'(x) = 1/2·(2x+1)^(-1/2)·2 = 1 gedeeld door wortel(2x+1).\n(b) f(4) = wortel(9) = 3. f'(4) = 1/wortel(9) = 1/3. Raaklijn: y = 1/3·(x-4) + 3 = 1/3 x + 5/3."}],"begrippen":[{"t":"Afgeleide","d":"de functie die de helling van f in elk punt geeft"},{"t":"Raaklijn","d":"de lijn y = f'(a)·(x − a) + f(a) die de grafiek in één punt raakt"},{"t":"Kettingregel","d":"de regel [f(g(x))]' = f'(g(x))·g'(x) voor samengestelde functies"},{"t":"Productregel","d":"de regel voor het differentiëren van een product van functies"},{"t":"Extremum","d":"een top of dal waar f'(x) = 0"},{"t":"Helling","d":"de steilheid van de grafiek in een punt, gelijk aan de afgeleide"},{"t":"Primitieve","d":"een functie waarvan de afgeleide f is, het omgekeerde van differentiëren"},{"t":"Buigpunt","d":"een punt waar de grafiek van hol naar bol overgaat, f''(x) = 0"},{"t":"Stationair punt","d":"een punt waar f'(x) = 0"},{"t":"Differentiëren","d":"het bepalen van de afgeleide van een functie"}],"sam":"<div class=\"sam-intro\">Met <strong>differentiëren</strong> vind je de <strong>helling</strong> en de <strong>raaklijn</strong>. De afgeleide van xⁿ is n·xⁿ⁻¹, van sin(x) is cos(x), van ln(x) is 1/x en van een constante 0. Voor samengestelde functies gebruik je de <strong>kettingregel</strong>. Waar f'(x) = 0 ligt een <strong>extremum</strong>.</div><div class=\"sam-head\">1. Afgeleiden</div><p>De <strong>afgeleide</strong> geeft de helling. Belangrijke regels: xⁿ → n·xⁿ⁻¹, een constante → 0, sin(x) → cos(x), cos(x) → −sin(x), eˣ → eˣ en ln(x) → 1/x. Voor een samengestelde functie geldt de <strong>kettingregel</strong>: [f(g(x))]' = f'(g(x))·g'(x).</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Kettingregel</div><div class=\"sam-formula-eq\">[f(g(x))]' = f'(g(x)) · g'(x)</div><div class=\"sam-formula-note\">Buitenste differentiëren, binnenste laten staan, maal de afgeleide van de binnenste.</div></div><div class=\"sam-head\">2. Raaklijn en extremen</div><p>De <strong>raaklijn</strong> aan f in x = a is y = f'(a)·(x − a) + f(a). Waar <strong>f'(x) = 0</strong> ligt een <strong>extremum</strong> (top of dal); is f'(x) > 0, dan stijgt f. Bij een product van functies gebruik je de <strong>productregel</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Afgeleide</div><div class=\"sam-definitie-body\">de functie die de helling van f in elk punt geeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Raaklijn</div><div class=\"sam-definitie-body\">de lijn y = f'(a)·(x − a) + f(a) die de grafiek in één punt raakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kettingregel</div><div class=\"sam-definitie-body\">de regel [f(g(x))]' = f'(g(x))·g'(x) voor samengestelde functies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Productregel</div><div class=\"sam-definitie-body\">de regel voor het differentiëren van een product van functies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Extremum</div><div class=\"sam-definitie-body\">een top of dal waar f'(x) = 0.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Helling</div><div class=\"sam-definitie-body\">de steilheid van de grafiek in een punt, gelijk aan de afgeleide.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Primitieve</div><div class=\"sam-definitie-body\">een functie waarvan de afgeleide f is, het omgekeerde van differentiëren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Buigpunt</div><div class=\"sam-definitie-body\">een punt waar de grafiek van hol naar bol overgaat, f''(x) = 0.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stationair punt</div><div class=\"sam-definitie-body\">een punt waar f'(x) = 0.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Differentiëren</div><div class=\"sam-definitie-body\">het bepalen van de afgeleide van een functie.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Afgeleide»</b> is helling in elk punt, terwijl <b>«Primitieve»</b> omgekeerde van afgeleide is. <b>«Raaklijn»</b> is raakt in één punt, terwijl <b>«Helling»</b> steilheid is. <b>«Kettingregel»</b> is voor f(g(x)), terwijl <b>«Productregel»</b> voor f(x)·g(x) is. <b>«Extremum»</b> is top of dal, terwijl <b>«Helling»</b> steilheid is.</div>"},"E":{"sv":[{"v":"Wat geeft de grootte van een vector a⃗ = (a₁, a₂) aan?","o":["|a⃗| = √(a₁² + a₂²), de lengte","a₁ + a₂","a₁ · a₂","a₁ − a₂"],"c":0,"d":3,"u":"De norm is de Euclidische lengte.","uo":["Klopt: de norm is de Euclidische lengte.","Nee, dat is de som van de kentallen.","Nee, dat is een product.","Nee, dat is een verschil."],"uh":"Norm: |a⃗| = √(a₁² + a₂²)."},{"v":"Twee vectoren zijn loodrecht. Wat geldt voor hun inproduct?","o":["het inproduct is 1","het inproduct is 0","het inproduct is negatief","het inproduct is maximaal"],"c":1,"d":2,"u":"Loodrecht betekent inproduct 0.","uo":["Nee, dat klopt niet.","Klopt: loodrecht betekent inproduct 0.","Nee, dat hoort bij een stompe hoek.","Nee, dat is bij dezelfde richting."],"uh":"Loodrechte vectoren: inproduct 0."},{"v":"Lijn l heeft rc = 3. Wat is de helling van een loodrechte lijn op l?","o":["1/3","3","−1/3","−3"],"c":2,"d":3,"u":"Rc₁·rc₂ = −1, dus −1/3.","uo":["Nee, dat product is niet −1.","Nee, dat is dezelfde helling.","Klopt: rc₁·rc₂ = −1, dus −1/3.","Nee, dat product is niet −1."],"uh":"Loodrecht: het product van de rc's is −1."},{"v":"Wat is het effect van parameter b in y = sin(bx)?","o":["b heeft geen effect","een grotere b geeft een grotere amplitude","b verschuift de grafiek omhoog","een grotere b geeft een kortere periode"],"c":3,"d":3,"u":"Periode = 2π/b, dus grotere b is kortere periode.","uo":["Nee, b bepaalt de periode.","Nee, de amplitude staat los van b.","Nee, dat doet een constante term.","Klopt: periode = 2π/b, dus grotere b is kortere periode."],"uh":"In sin(bx): grotere b, kortere periode (2π/b)."},{"v":"Hoe tel je twee vectoren grafisch op?","o":["kop-op-staart: de staart van de tweede aan de kop van de eerste","je legt ze evenwijdig naast elkaar","je trekt ze van elkaar af","je telt alleen de lengtes op"],"c":0,"d":2,"u":"De som is de pijl van begin naar eind.","uo":["Klopt: de som is de pijl van begin naar eind.","Nee, zo tel je niet op.","Nee, dat is aftrekken.","Nee, richting telt ook."],"uh":"Vectoren optellen: kop-op-staart."},{"v":"Waar staat het ezelsbruggetje SOH-CAH-TOA voor?","o":["de zijden van een rechthoek","sin = O/H, cos = A/H, tan = O/A","de oppervlakte van een driehoek","de omtrek van een cirkel"],"c":1,"d":2,"u":"De verhoudingen in een rechthoekige driehoek.","uo":["Nee, het gaat over hoeken.","Klopt: de verhoudingen in een rechthoekige driehoek.","Nee, niet over oppervlakte.","Nee, niet over omtrek."],"uh":"SOH-CAH-TOA: sin=O/H, cos=A/H, tan=O/A."},{"v":"Hoe controleer je of punt P(3, 4) op de cirkel (x − 1)² + (y − 2)² = 9 ligt?","o":["bereken de rc van P","kijk of P het middelpunt is","bereken (3 − 1)² + (4 − 2)² en vergelijk met 9","tel 3 en 4 op"],"c":2,"d":3,"u":"Als de uitkomst 9 is, ligt P op de cirkel.","uo":["Nee, dat is niet relevant.","Nee, dat is het middelpunt.","Klopt: als de uitkomst 9 is, ligt P op de cirkel.","Nee, dat zegt niets."],"uh":"Punt op cirkel: vul in en vergelijk met r²."},{"v":"Wat zegt een inproduct a⃗·b⃗ = −15 over de hoek tussen de vectoren?","o":["de vectoren zijn gelijk","de hoek is recht (90°)","de hoek is scherp (kleiner dan 90°)","de hoek is stomp (groter dan 90°)"],"c":3,"d":3,"u":"Een negatief inproduct hoort bij een stompe hoek.","uo":["Nee, dat volgt er niet uit.","Nee, dan zou het 0 zijn.","Nee, dan zou het positief zijn.","Klopt: een negatief inproduct hoort bij een stompe hoek."],"uh":"Negatief inproduct: stompe hoek."},{"v":"Wat is de standaardvorm van een cirkelvergelijking?","o":["(x − a)² + (y − b)² = r²","y = a·x + b","a·x² + b·x + c = 0","x² + y² = x"],"c":0,"d":2,"u":"Middelpunt (a, b) en straal r.","uo":["Klopt: middelpunt (a, b) en straal r.","Nee, dat is een lijn.","Nee, dat is een kwadratische vergelijking.","Nee, dat is geen standaardvorm."],"uh":"Cirkel: (x − a)² + (y − b)² = r²."},{"v":"Hoe controleer je of twee lijnen loodrecht op elkaar staan?","o":["rc₁ = rc₂","rc₁ × rc₂ = −1","rc₁ + rc₂ = 0","ze snijden de x-as"],"c":1,"d":3,"u":"Bij loodrecht is het product van de rc's −1.","uo":["Nee, dan zijn ze evenwijdig.","Klopt: bij loodrecht is het product van de rc's −1.","Nee, dat betekent tegengesteld, niet loodrecht.","Nee, dat zegt niets."],"uh":"Loodrecht: rc₁ × rc₂ = −1."},{"v":"Wat is het middelpunt van het lijnstuk van A(x₁, y₁) naar B(x₂, y₂)?","o":["(x₂ − x₁, y₂ − y₁)","(x₁ · x₂, y₁ · y₂)","((x₁ + x₂)/2, (y₁ + y₂)/2)","(x₁ + x₂, y₁ + y₂)"],"c":2,"d":3,"u":"Het middelpunt is het gemiddelde van de coördinaten.","uo":["Nee, dat is de verschilvector.","Nee, dat is een product.","Klopt: het middelpunt is het gemiddelde van de coördinaten.","Nee, je moet nog delen door 2."],"uh":"Middelpunt: het gemiddelde van de coördinaten."},{"v":"Wat is de norm van een vector?","o":["de hoek met de x-as","de richting van de vector","het inproduct met zichzelf","de lengte van de vector"],"c":3,"d":2,"u":"De norm is de lengte.","uo":["Nee, dat is de richtingshoek.","Nee, dat is de richting.","Nee, dat is het kwadraat van de norm.","Klopt: de norm is de lengte."],"uh":"Norm: de lengte van een vector."},{"v":"De lengte van een vector, wortel uit a-een kwadraat plus a-twee kwadraat. Welk begrip past hierbij?","o":["Norm","Vector","Loodrecht","Cirkelvergelijking"],"c":0,"d":1,"u":"De lengte van een vector, wortel uit a-een kwadraat plus a-twee kwadraat. Dat past bij Norm: lengte van een vector.","uo":["Klopt: lengte van een vector.","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Loodrecht: rc₁·rc₂ = −1.","Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r²."],"uh":"Norm: lengte van een vector."},{"v":"Twee lijnen waarvan het product van de hellingen min een is. Om welk begrip gaat het?","o":["Inproduct","Loodrecht","Vector","Kop-op-staart-methode"],"c":1,"d":1,"u":"Twee lijnen waarvan het product van de hellingen min een is. Dat past bij Loodrecht: rc₁·rc₂ = −1.","uo":["Nee, dat hoort bij Inproduct: som van producten.","Klopt: rc₁·rc₂ = −1.","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Loodrecht: rc₁·rc₂ = −1."},{"v":"Ze staan haaks op elkaar. Welk begrip herken je hier?","o":["Vector","Inproduct","Loodrecht","Kop-op-staart-methode"],"c":2,"d":1,"u":"Ze staan haaks op elkaar. Dat past bij Loodrecht: rc₁·rc₂ = −1.","uo":["Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Inproduct: som van producten.","Klopt: rc₁·rc₂ = −1.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Loodrecht: rc₁·rc₂ = −1."},{"v":"De herhaallengte van een sinus. Wat is hier aan de hand?","o":["Kop-op-staart-methode","Middelpunt","Sinusregel","Periode"],"c":3,"d":1,"u":"De herhaallengte van een sinus. Dat past bij Periode: 2π/b.","uo":["Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar.","Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Klopt: 2π/b."],"uh":"Periode: 2π/b."},{"v":"Na hoeveel de sinusgrafiek zich herhaalt, 2 pi gedeeld door b. Welk begrip past hierbij?","o":["Periode","Middelpunt","Sinusregel","Kop-op-staart-methode"],"c":0,"d":1,"u":"Na hoeveel de sinusgrafiek zich herhaalt, 2 pi gedeeld door b. Dat past bij Periode: 2π/b.","uo":["Klopt: 2π/b.","Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Periode: 2π/b."},{"v":"De regel bij drie zijden of een ingesloten hoek. Om welk begrip gaat het?","o":["Inproduct","Cosinusregel","Middelpunt","Kop-op-staart-methode"],"c":1,"d":1,"u":"De regel bij drie zijden of een ingesloten hoek. Dat past bij Cosinusregel: drie zijden of ingesloten hoek.","uo":["Nee, dat hoort bij Inproduct: som van producten.","Klopt: drie zijden of ingesloten hoek.","Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Cosinusregel: drie zijden of ingesloten hoek."},{"v":"De regel a/sin A is b/sin B. Welk begrip herken je hier?","o":["Middelpunt","Cosinusregel","Sinusregel","Inproduct"],"c":2,"d":2,"u":"De regel a/sin A is b/sin B. Dat past bij Sinusregel: a/sin A = b/sin B.","uo":["Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek.","Klopt: a/sin A = b/sin B.","Nee, dat hoort bij Inproduct: som van producten."],"uh":"Sinusregel: a/sin A = b/sin B."},{"v":"Bij twee hoeken en een zijde reken je met a gedeeld door sin A. Wat is hier aan de hand?","o":["Norm","Cirkelvergelijking","Kop-op-staart-methode","Sinusregel"],"c":3,"d":1,"u":"Bij twee hoeken en een zijde reken je met a gedeeld door sin A. Dat past bij Sinusregel: a/sin A = b/sin B.","uo":["Nee, dat hoort bij Norm: lengte van een vector.","Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar.","Klopt: a/sin A = b/sin B."],"uh":"Sinusregel: a/sin A = b/sin B."},{"v":"De standaardvorm van een cirkel. Welk begrip past hierbij?","o":["Cirkelvergelijking","Middelpunt","Inproduct","Vector"],"c":0,"d":2,"u":"De standaardvorm van een cirkel. Dat past bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","uo":["Klopt: (x − a)² + (y − b)² = r².","Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Inproduct: som van producten.","Nee, dat hoort bij Vector: grootte en richting."],"uh":"Cirkelvergelijking: (x − a)² + (y − b)² = r²."},{"v":"De vorm x min a in het kwadraat plus y min b in het kwadraat is r kwadraat. Om welk begrip gaat het?","o":["Kop-op-staart-methode","Cirkelvergelijking","Vector","Loodrecht"],"c":1,"d":1,"u":"De vorm x min a in het kwadraat plus y min b in het kwadraat is r kwadraat. Dat past bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","uo":["Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar.","Klopt: (x − a)² + (y − b)² = r².","Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Loodrecht: rc₁·rc₂ = −1."],"uh":"Cirkelvergelijking: (x − a)² + (y − b)² = r²."},{"v":"De som van de producten van de kentallen. Welk begrip herken je hier?","o":["Middelpunt","Norm","Inproduct","Cosinusregel"],"c":2,"d":2,"u":"De som van de producten van de kentallen. Dat past bij Inproduct: som van producten.","uo":["Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Nee, dat hoort bij Norm: lengte van een vector.","Klopt: som van producten.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek."],"uh":"Inproduct: som van producten."},{"v":"Het grafisch optellen van vectoren. Wat is hier aan de hand?","o":["Sinusregel","Inproduct","Vector","Kop-op-staart-methode"],"c":3,"d":3,"u":"Het grafisch optellen van vectoren. Dat past bij Kop-op-staart-methode: vectoren achter elkaar.","uo":["Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Inproduct: som van producten.","Nee, dat hoort bij Vector: grootte en richting.","Klopt: vectoren achter elkaar."],"uh":"Kop-op-staart-methode: vectoren achter elkaar."},{"v":"Een grootheid met grootte en richting. Welk begrip past hierbij?","o":["Vector","Periode","Kop-op-staart-methode","Inproduct"],"c":0,"d":1,"u":"Een grootheid met grootte en richting. Dat past bij Vector: grootte en richting.","uo":["Klopt: grootte en richting.","Nee, dat hoort bij Periode: 2π/b.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar.","Nee, dat hoort bij Inproduct: som van producten."],"uh":"Vector: grootte en richting."},{"v":"Bij drie zijden of twee zijden met de ingesloten hoek. Om welk begrip gaat het?","o":["Sinusregel","Cosinusregel","Inproduct","Norm"],"c":1,"d":2,"u":"Bij drie zijden of twee zijden met de ingesloten hoek. Dat past bij Cosinusregel: drie zijden of ingesloten hoek.","uo":["Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Klopt: drie zijden of ingesloten hoek.","Nee, dat hoort bij Inproduct: som van producten.","Nee, dat hoort bij Norm: lengte van een vector."],"uh":"Cosinusregel: drie zijden of ingesloten hoek."},{"v":"De lengte van een vector. Welk begrip herken je hier?","o":["Periode","Inproduct","Norm","Kop-op-staart-methode"],"c":2,"d":3,"u":"De lengte van een vector. Dat past bij Norm: lengte van een vector.","uo":["Nee, dat hoort bij Periode: 2π/b.","Nee, dat hoort bij Inproduct: som van producten.","Klopt: lengte van een vector.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Norm: lengte van een vector."},{"v":"Het midden van een lijnstuk. Wat is hier aan de hand?","o":["Norm","Sinusregel","Kop-op-staart-methode","Middelpunt"],"c":3,"d":1,"u":"Het midden van een lijnstuk. Dat past bij Middelpunt: gemiddelde van de coördinaten.","uo":["Nee, dat hoort bij Norm: lengte van een vector.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar.","Klopt: gemiddelde van de coördinaten."],"uh":"Middelpunt: gemiddelde van de coördinaten."},{"v":"Een pijl met een grootte en een richting. Welk begrip past hierbij?","o":["Vector","Norm","Sinusregel","Kop-op-staart-methode"],"c":0,"d":2,"u":"Een pijl met een grootte en een richting. Dat past bij Vector: grootte en richting.","uo":["Klopt: grootte en richting.","Nee, dat hoort bij Norm: lengte van een vector.","Nee, dat hoort bij Sinusregel: a/sin A = b/sin B.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Vector: grootte en richting."},{"v":"Het gemiddelde van de coördinaten van de twee eindpunten. Om welk begrip gaat het?","o":["Cirkelvergelijking","Middelpunt","Inproduct","Cosinusregel"],"c":1,"d":3,"u":"Het gemiddelde van de coördinaten van de twee eindpunten. Dat past bij Middelpunt: gemiddelde van de coördinaten.","uo":["Nee, dat hoort bij Cirkelvergelijking: (x − a)² + (y − b)² = r².","Klopt: gemiddelde van de coördinaten.","Nee, dat hoort bij Inproduct: som van producten.","Nee, dat hoort bij Cosinusregel: drie zijden of ingesloten hoek."],"uh":"Middelpunt: gemiddelde van de coördinaten."},{"v":"Je vermenigvuldigt de kentallen en telt op; nul betekent loodrecht. Welk begrip herken je hier?","o":["Vector","Middelpunt","Inproduct","Kop-op-staart-methode"],"c":2,"d":1,"u":"Je vermenigvuldigt de kentallen en telt op; nul betekent loodrecht. Dat past bij Inproduct: som van producten.","uo":["Nee, dat hoort bij Vector: grootte en richting.","Nee, dat hoort bij Middelpunt: gemiddelde van de coördinaten.","Klopt: som van producten.","Nee, dat hoort bij Kop-op-staart-methode: vectoren achter elkaar."],"uh":"Inproduct: som van producten."},{"v":"Je legt de staart van de tweede vector aan de kop van de eerste. Wat is hier aan de hand?","o":["Loodrecht","Inproduct","Periode","Kop-op-staart-methode"],"c":3,"d":2,"u":"Je legt de staart van de tweede vector aan de kop van de eerste. Dat past bij Kop-op-staart-methode: vectoren achter elkaar.","uo":["Nee, dat hoort bij Loodrecht: rc₁·rc₂ = −1.","Nee, dat hoort bij Inproduct: som van producten.","Nee, dat hoort bij Periode: 2π/b.","Klopt: vectoren achter elkaar."],"uh":"Kop-op-staart-methode: vectoren achter elkaar."}],"oe":[{"bron":"HAVO Wiskunde B CE 2023 Tijdvak 2 Meetkunde (geen afbeelding)","ctx":"Gegeven: A(1, 2) en B(5, 6).","v":"(a) Bereken afstand AB.\n(b) Bepaal middelpunt M van AB.\n(c) Geef de vergelijking van de loodlijn op AB door M.","o":[""],"c":0,"u":"(a) AB = wortel((5-1)²+(6-2)²) = wortel(32) = 4√2 ≈ 5,66.\n(b) M = (3, 4).\n(c) Helling AB = 1, loodlijn rc = -1. Door M(3,4): y-4 = -(x-3) → y = -x+7."},{"bron":"HAVO Wiskunde B CE 2022 Tijdvak 1 Cirkel (geen afbeelding)","ctx":"Gegeven: x² + y² - 6x + 4y - 3 = 0.","v":"(a) Schrijf om naar standaardvorm via kwadraat aanvullen.\n(b) Geef het middelpunt en de straal.","o":[""],"c":0,"u":"(a) (x²-6x+9)+(y²+4y+4) = 3+9+4 = 16 → (x-3)²+(y+2)² = 16.\n(b) Middelpunt M(3,-2), straal r = 4."},{"bron":"HAVO Wiskunde B CE 2024 Tijdvak 2 Goniometrie (geen afbeelding)","ctx":"In driehoek PQR: PQ = 8, PR = 6 en hoek P = 60°.","v":"(a) Bereken QR met de cosinusregel.\n(b) Bereken de oppervlakte van driehoek PQR.","o":[""],"c":0,"u":"(a) QR² = 64+36-2·8·6·cos(60°) = 100-48 = 52 → QR = 2√13 ≈ 7,21.\n(b) Opp = ½·8·6·sin(60°) = 24·(√3/2) = 12√3 ≈ 20,78 cm²."}],"begrippen":[{"t":"Vector","d":"een grootheid met een grootte en een richting"},{"t":"Norm","d":"|a⃗| = √(a₁² + a₂²): de lengte van een vector"},{"t":"Inproduct","d":"a₁b₁ + a₂b₂; 0 bij loodrecht, negatief bij een stompe hoek"},{"t":"Cirkelvergelijking","d":"de standaardvorm (x − a)² + (y − b)² = r²"},{"t":"Middelpunt","d":"van A naar B: ((x₁ + x₂)/2, (y₁ + y₂)/2)"},{"t":"Sinusregel","d":"a/sin A = b/sin B, bij twee hoeken en een zijde"},{"t":"Cosinusregel","d":"de regel bij drie zijden of twee zijden met de ingesloten hoek"},{"t":"Loodrecht","d":"twee lijnen met rc₁·rc₂ = −1 of vectoren met inproduct 0"},{"t":"Periode","d":"de lengte 2π/b waarna y = sin(bx) zich herhaalt"},{"t":"Kop-op-staart-methode","d":"het grafisch optellen van vectoren door ze achter elkaar te leggen"}],"sam":"<div class=\"sam-intro\">In de analytische meetkunde reken je met <strong>vectoren</strong>, hun <strong>norm</strong> en het <strong>inproduct</strong>. Je herkent <strong>loodrechte</strong> lijnen (rc₁·rc₂ = −1), stelt de <strong>cirkelvergelijking</strong> (x − a)² + (y − b)² = r² op, en bepaalt het <strong>middelpunt</strong> van een lijnstuk.</div><div class=\"sam-head\">1. Vectoren</div><p>De <strong>norm</strong> (grootte) van vector a⃗ is |a⃗| = √(a₁² + a₂²). Het <strong>inproduct</strong> a⃗·b⃗ is 0 bij <strong>loodrechte</strong> vectoren, negatief bij een stompe hoek. Vectoren tel je grafisch op met de <strong>kop-op-staart</strong>-methode.</p><div class=\"sam-head\">2. Lijnen en cirkels</div><p>Twee lijnen staan <strong>loodrecht</strong> als rc₁·rc₂ = −1; de loodlijn op rc = 3 heeft rc = −1/3. De <strong>cirkelvergelijking</strong> is (x − a)² + (y − b)² = r². Het <strong>middelpunt</strong> van het lijnstuk van A(x₁, y₁) naar B(x₂, y₂) is ((x₁ + x₂)/2, (y₁ + y₂)/2). Voor y = sin(bx) geldt: een grotere b geeft een kortere periode.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vector</div><div class=\"sam-definitie-body\">een grootheid met een grootte en een richting.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Norm</div><div class=\"sam-definitie-body\">|a⃗| = √(a₁² + a₂²): de lengte van een vector.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inproduct</div><div class=\"sam-definitie-body\">a₁b₁ + a₂b₂; 0 bij loodrecht, negatief bij een stompe hoek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cirkelvergelijking</div><div class=\"sam-definitie-body\">de standaardvorm (x − a)² + (y − b)² = r².</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Middelpunt</div><div class=\"sam-definitie-body\">van A naar B: ((x₁ + x₂)/2, (y₁ + y₂)/2).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sinusregel</div><div class=\"sam-definitie-body\">a/sin A = b/sin B, bij twee hoeken en een zijde.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cosinusregel</div><div class=\"sam-definitie-body\">de regel bij drie zijden of twee zijden met de ingesloten hoek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Loodrecht</div><div class=\"sam-definitie-body\">twee lijnen met rc₁·rc₂ = −1 of vectoren met inproduct 0.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Periode</div><div class=\"sam-definitie-body\">de lengte 2π/b waarna y = sin(bx) zich herhaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kop-op-staart-methode</div><div class=\"sam-definitie-body\">het grafisch optellen van vectoren door ze achter elkaar te leggen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Vector»</b> is grootte en richting, terwijl <b>«Norm»</b> lengte van een vector is. <b>«Norm»</b> is lengte van een vector, terwijl <b>«Inproduct»</b> som van producten is. <b>«Cirkelvergelijking»</b> is (x − a)² + (y − b)² = r², terwijl <b>«Middelpunt»</b> gemiddelde van de coördinaten is. <b>«Sinusregel»</b> is a/sin A = b/sin B, terwijl <b>«Cosinusregel»</b> drie zijden of ingesloten hoek is.</div>"}});